-- ============================================================================
-- 214 — اصلاح نص القرار الوزارى 135/1993 باللائحة التنفيذية لقانون سوق رأس المال (457 مادة) من نسخة الهيئة العامة للرقابة المالية المحدَّثة حتى 30/4/2025 (PDF)
-- ----------------------------------------------------------------------------
-- المشكلة: النص المخزَّن من استخراج PDF فيه (1) تمطيط حروف (تتتت...) داخل كلمات عشرات المواضع (مثل "ستتتتتخدام" بدل "استخدام")،
--          (2) عناوين الأبواب والفصول والفروع وعناوين المواد مدسوسة فى آخر المادة السابقة (فى 76 موضعاً)، (3) الأرقام الترتيبية (أولاً/ثانياً/
--          البند الأول...) مفصولة عن بنودها أو ساقطة أو مُبدَّلة المواضع (المواد 7 و17 و35 و85 و125 و170 وغيرها)، (4) علامات التنوين منفصلة عن حروفها،
--          (5) كلمات لاتينية معكوسة (Sub-account و ESG Funds)، (6) أسطر مكسورة عند حدود الصفحة بدل الفقرات، (7) رقم البند ملتصق بالنص ("13.تاريخ").
-- الإصلاح: أُعيد بناء النص من أحرف الملف نفسه بإحداثياتها (لا من طبقة النص المكسورة)، وقورنت المواد الـ457 مادةً مادة بالنص المخزَّن:
--          كل الفروق محصورة فى الأنواع المذكورة ولا يوجد فرق حرفى آخر غير مفسَّر؛ وقورن النص بقراءة OCR مستقلة لصفحات الملف الـ176
--          (56,335 كلمة: لا كلمة ناقصة أو مشوهة)، وفحصت بصرياً مواضع الاشتباه. عناوين الأبواب والفصول لا تدخل نص المادة، وحقل الموقع
--          الهرمى (hierarchical_location) لا يُمس فى هذه الهجرة. أخطاء المطبعة الموجودة فى الملف الرسمى نفسه (مثل التصاق بندين فى سطر واحد بالمادة 16) بقيت كما وردت.
-- الضمان: كل مادة تُحدَّث فقط إذا كان md5 نصها الحالى أحد النصين المقيسين (قبل/بعد 208) أو كانت "بصمتها الحرفية" (الحروف والأرقام بعد حذف
--          ا أ إ آ ل ه والعلامات) مطابقة لبصمة النص المتوقع؛ غير ذلك: تحذير وتخطٍّ دون كتابة. النص القديم يُحفظ فى migration_214_backup.
--          نسخ article_versions المطابقة تُحدَّث معها. embeddings لا تُمس. قابلة لإعادة التشغيل.
-- ============================================================================

CREATE TABLE IF NOT EXISTS migration_214_backup (
  article_id uuid NOT NULL,
  version_id uuid,
  old_body   text NOT NULL,
  saved_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_214_backup_art ON migration_214_backup (article_id) WHERE version_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_214_backup_ver ON migration_214_backup (version_id) WHERE version_id IS NOT NULL;

DO $m214$
DECLARE
  r record;
  v_law uuid; v_aid uuid; v_cur text;
  v_ok_art int := 0; v_ok_ver int := 0; v_done int := 0; v_skip int := 0; v_n int;
BEGIN
  SELECT l.id INTO v_law FROM laws l
   WHERE l.country_code = 'EG' AND l.kind = 'ministerial_decision' AND l.law_no = 135 AND l.law_year = 1993;
  IF v_law IS NULL THEN
    RAISE WARNING '[214] القرار 135/1993 غير موجود — تخطّى';
    RETURN;
  END IF;

  FOR r IN SELECT * FROM (VALUES
    (1, -1, ARRAY['ac255a31ff637aeb0bd4a60c346ea0eb']::text[], ARRAY['9b9ad674cab3cc1edc8174715ae8a237']::text[], 'ac255a31ff637aeb0bd4a60c346ea0eb', replace($b$يعمل بأحكام اللائحة التنفيذية لقانون تنظيم سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 المرافقة لهذا القرار
ويعمل فيما لم يرد فيه نص خاص باللائحة التنفيذية للقانون رقم 159 لسنة 1992 لسنة 1981 المشار إليه.$b$, E'\n', E'\r\n')),
    (2, -1, ARRAY['480a257ef922ab89721081278c9a9433']::text[], ARRAY['5a9274eb4bc050d5096be1d8766c4cda']::text[], '87fea1775b32dfa3b97ff7f67fa625ab', replace($b$في تطبيق أحكام اللائحة المرافقة يقصد بالقانون القانون رقم 95 لسنة 1992، وبالوزير وزير الاقتصاد والتجارة
الخارجية، وبالهيئة أو الجهة الإدارية أينما وردتا في اللائحة المرافقة أو اللائحة التنفيذية للقانون رقم 159 لسنة
1981 بالنسبة إلى شركات الاكتتاب العام أو في تطبيق أحكام القانون رقم 95 لسنة 1992 الهيئة العامة لسوق المال.$b$, E'\n', E'\r\n')),
    (3, -1, ARRAY['fb8016bd50b21289e4d428e5d673514f']::text[], ARRAY['083c28b6c30cbeead8990e3e77da5e5f']::text[], 'e0f836fbe5dbd158bc79adbe51f33a3a', replace($b$ينشر هذا القرار في الوقائع المصرية ويعمل به من اليوم التالي لتاريخ نشره.
صر في 15 شوال سنة 1413 هـ الموافق 7 أبريل 1993$b$, E'\n', E'\r\n')),
    (1, 0, ARRAY['ba81d351e42e8bf36af1580d2760165a']::text[], ARRAY['f9cfe42f106e1b812db6ef51649e5d63']::text[], 'bade36e136561f4c04a5863a07153bfd', replace($b$يكون للشركة رأس مال مصدر، ويجوز أن يحدد النظام الأساسي للشركة رأس مال مرخصا به. ويقسم رأس مال شركة المساهمة وحصة الشركاء غير المتضامنين في شركات التوصية بالأسهم إلى أسهم اسمية متساوية القيمة في كل إصدار.
وفي جميع الإصدارات لا تجاوز مصاريف الإصدار الحد الذي يصدر به قرار من الهيئة.
*تم إلغاء الاحكام المنظمة للأسهم لحامله الواردة بالمادتين (1 الفقرة الثانية) ، (37) وفقا لقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (2, 0, ARRAY['a3f97536a851be69a585ab73f6d4a5c0']::text[], ARRAY['b030fd585c3539cba221c229f46983c6']::text[], 'a892cfa452535c16d00c99085065a7cb', replace($b$يحدد نظام الشركة القيمة الاسمية للسهم بحيث لا تقل عن عشرة قروش ولا تزيد على ألف جنيه ويشترط أن يكون رأس المال المصدر مكتتبا فيه بالكامل، وبمراعاة أحكام الحصص العينية، يجب على كل مكتتب أن يدفع نقدا، أو بوسيلة دفع أخرى مقبولة قانونا، الربع على الأقل من القيمة الاسمية للأسهم النقدية فور الاكتتاب بالإضافة إلى مصروفات الإصدار.
ولا يجوز أن يكون الدفع بسند شخصي على المكتتب أو بتقديم منقولات أو عقارات أو حق معنوي ولو كانت قيمتها تساوي الربع الواجب أداؤه.
كما لا يجوز الدفع بطريق المقاصة بين ما يكون للمكتتب من دين على أحد المؤسسين ومقدار قيمة المبلغ الواجب أداؤه.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (3, 0, ARRAY['aa3b6a8c91b8ea26b27cf688f1188c4b']::text[], ARRAY['cb3dd313b136be941a310b7bff06495c']::text[], '8ab590215fa762a3a654ae5050ae7fc3', replace($b$يشترط لصحة الاكتتاب سواء كان عاما أو غير عام الشروط الآتية:
1. أن يكون كاملا بأن يغطي جميع أسهم الشركة التي تمثل رأس المال المصدر في شركات المساهمة، أو الحصص والأسهم في شركات التوصية بالأسهم.
2. أن يكون باتا غير معلق على شرط وفوريا غير مضاف إلى أجل، فإذا علق الاكتتاب على شرط بطل الشرط وصح الاكتتاب وألزم المكتتب به، وإذا كان مضافا إلى أجل بطل الأجل وكان الاكتتاب فوريا.
3. أن يكون جديا لا صوريا
4. ألا يقل ما يدفعه المكتتب عند التأسيس من القيمة الاسمية للأسهم النقدية عن ربع القيمة.
5. أن تكون الأسهم التي تمثل الحصص العينية قد تم الوفاء بقيمتها كاملة.$b$, E'\n', E'\r\n')),
    (4, 0, ARRAY['6c7e30a23dc72abe1b05c57d62a3e468']::text[], ARRAY['0d85a086715e03faf0c520a948c70d50']::text[], '6c7e30a23dc72abe1b05c57d62a3e468', replace($b$ملغاة
*ملغاة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018 اعتبارا من تاريخ 17 يناير 2019.$b$, E'\n', E'\r\n')),
    (5, 0, ARRAY['6c7e30a23dc72abe1b05c57d62a3e468']::text[], ARRAY['0d85a086715e03faf0c520a948c70d50']::text[], '6c7e30a23dc72abe1b05c57d62a3e468', replace($b$ملغاة
*ملغاة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018 اعتبارا من تاريخ 17 يناير 2019.$b$, E'\n', E'\r\n')),
    (6, 0, ARRAY['5308865a0e73472c4250d516e4a2e3d8']::text[], ARRAY['36d59e7a8533c0ad81865c7f9bf6c579']::text[], '1858c668f278fbc4a7897f8ad1cf3b86', replace($b$يتم قيد المبالغ المدفوعة من المكتتبين على صكوك الأسهم.
على مجلس الإدارة أو الشريك أو الشركاء المديرين، بحسب الأحوال، طلب أداء الباقي خلال مدة لا تجاوز خمس سنوات من تاريخ تأسيس الشركة، وذلك بالطريقة التي يقررها النظام الأساسي للشركة وفي المواعيد التي تحددها الجمعية العامة العادية، على أن يعلن عن تلك المواعيد قبل حلولها بخمسة عشر يوما على الأقل.ويحق لمجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال أن يقوم ببيع الأسهم التي يتأخر أصحابها عن سداد المبالغ المطلوبة عنها في المواعيد المحددة لحساب أصحابها وعلى ذمتهم وتحت مسئوليتهم وذلك بعد مضي ستين يوما على الأقل من تاريخ ابلاغهم بذلك. وتلغى حتما صكوك الأسهم المبيعة بأسماء أصحابها، وتبلغ بورصة الأوراق المالية المقيدة بها أسهم الشركة بذلك، على أن تسلم صكوك جديدة للمشترين عوضا عنها تحمل ذات أرقامها يشار فيها إلى أنها بديلة للصكوك الملغاة.
ويخصم مجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال من ثمن البيع ما يكون مطلوبا للشركة من مصاريف، ويحاسب المساهم الذي بيعت أسهمه على ما قد يوجد من الزيادة ويطالبه بالفرق عند وجود عجز.
كل ذلك مع عدم الإخلال بحق الشركة في أن تستعمل قبل المساهم المتأخر في الوقت ذاته أو في وقت آخر جميع الحقوق التي تخولها لها الأحكام العامة في القانون.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (7, 0, ARRAY['7f15bc323857786554d291ecd6dd2ab6']::text[], ARRAY['06279ef305cb56fe0ca65fe5bc7b5a8e']::text[], '49742a7066dbeb6e433c460d58709846', replace($b$على كل شركة ترغب في إصدار أوراق مالية أن تخطر الهيئة بذلك ويجب أن يتضمن الإخطار ويرفق به البيانات والمستندات الآتية:
أولا-بالنسبة لإصدار الأسهم عند التأسيس
1. أنواع الأسهم المزمع إصدارها وشروط طرحها
2. إجمالي عدد الأسهم وبيان ما قد يطرح منها للإكتتاب العام.
3. مصاريف الإصدار في حالة تقريرها وكيفية حسابها.
4. شهادة من الجهة الإدارية المختصة تفيد الوفاء بالقدر المطلوب سداده قانونا من رأس المال.
5. الإيصال الدال على سداد الرسوم المقررة للهيئة.
ثانيا - بالنسبة لإصدار أسهم لزيادة رأس المال:
1. تحديد قيمة أسهم الزيادة وتقرير مراقب الحسابات عنها طبقا لأحكام المادتين (17 أو 17 مكررا) من هذه اللائحة إذا كانت الأسهم مطروحة لغير المساهمين بالشركة.
2. نوع الأسهم المزمع إصدارها وشروط طرحها.
3. بيان المساهمات في رأس المال وتوزيعاته وما إذا كانت الشركة مقيدة ببورصة الأوراق المالية ونوع الجدول المقيدة بمصاريف الإصدار في حالة تقريرها وكيفية حسابها.
4. شهادة من الجهة الإدارية المختصة تفيد الوفاء بالقدر المطلوب سداده قانونا من الزيادة.
5. الإيصال الدال على سداد الرسوم المقررة للهيئة.
6. وللهيئة الاعتراض على إصدار أسهم الزيادة في حالة عدم مراعاة حكمي المادتين (17 أو 17 مكررا) من هذه اللائحة أوعدم استيفاء المستندات والبيانات المنصوص عليها في هذه المادة.
ثالثا - بالنسبة لإصدار الأوراق المالية الأخرى:
1. نسخة من النظام الأساسي للشركة وفقا لآخر تعديل.
2. قرار الجمعية العامة غير العادية بإصدار الأوراق المالية والمستندات والتقارير التي عرضت عليها في هذا الشأن. 3. بيان أعضاء مجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال.
4. موجز للقوائم والبيانات المالية المعتمدة من مراقبي الحسابات عن السنوات الثلاثة السابقة أو عن المدة من تاريخ التأسيس أيهما أقل
5. نوع الأوراق المالية المزمع إصدارها وبيانات وافية عنها وما إذا كان يتم طرحها للاكتتاب العام من عدمه، وما إذا كان الإصدار دفعة واحدة أم دفعات متعددة.
6. الإيصال الدال على سداد الرسوم المقررة للهيئة.
7. شروط ومواعيد استرداد الأوراق المالية.
8. بيان المساهمات في رأس المال وتوزيعاته، وما إذا كانت الشركة مقيدة ببورصة الأوراق المالية.
9. مصاريف الإصدار وكيفية حسابها.
وفي جميع الأحوال يجب على الشركة إخطار الهيئة بتمام إجراءات الإصدار خلال خمسة عشر يوما من تاريخ تمامها أو من تاريخ القيد في السجل التجاري في الحالات التي يلزم فيها هذا القيد، كما يجب على السجل المختص خلال ذات المدة إبلاغ الهيئة بذلك القيد.
وعلى كل شخص اعتباري مصري أو غير مصري لا يتخذ شكل شركة يرغب في إصدار أوراق مالية بخلاف الأسهم أن يخطر الهيئة بذلك، ويجب أن يتضمن الإخطار البيانات وأن ترفق به المستندات المشار إليها في البند ثالثا (4، 5، 6، 7، 9) من هذه المادة بالإضافة إلى:
1. نسخة من السند القانوني لإنشاء الشخص الاعتباري، ونظامه الأساسي أو ما يعادله وفقا لأخر تعديل.
2. قرار السلطة المختصة قانونا بإصدار الأوراق المالية في جهة الإصدار والمستندات والتقارير التي عرضت عليها في هذا الشأن.
3. بيان بمصادر التمويل وحقوق الملكية طبقا لأحدث قوائم مالية.
4. بيان عن مدة الورقة المالية وملخص لمصادر التدفقات النقدية ونسب السيولة والهيكل المالي لجهة الإصدار، وتقرير مراقب الحسابات عن التوقعات المستقبلية وفقا لمعايير المراجعة المصرية.
5. شهادة التصنيف الائتماني لمصدر الورقة المالية، أو للجهة الضامنة للورقة المالية (إن وجد) على أن يتم موافاة الهيئة بشهادة التصنيف الائتماني للورقة المالية المزمع إصدارها فور موافاة الهيئة بالمشروع النهائي لنشرة الاكتتاب العام.
ويجب إخطار الهيئة بتمام إجراءات الإصدار خلال خمسة عشر يوما من تاريخ إتمامها، وفي جميع الأحوال يكون للهيئة الحق في استبعاد أي من التقارير والمستندات المشار إليها أو الإضافة إليها بما يتفق مع الطبيعة القانونية لجهة الإصدار.
*معدلة بقرار وزير الإستثمار رقم 45 لسنة 2015.$b$, E'\n', E'\r\n')),
    (8, 0, ARRAY['1fbd59d7a38a7b4105d2a269b4e23267']::text[], ARRAY['73cbe07c8b651b2646fd149af1d8731b']::text[], '1fbd59d7a38a7b4105d2a269b4e23267', replace($b$ملغاة
*ملغاة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (9, 0, ARRAY['caf6c04350da4b0c47f9b3c727a924ef']::text[], ARRAY['54ddb0b550da803824dfbc9741a00306']::text[], '74d765b2b16fd642586b38b8799d39ba', replace($b$يجوز أن ينص النظام على تقرير بعض الامتيازات لبعض أنواع الأسهم الاسمية وذلك في التصويت أو الأرباح أو ناتج التصفية على أن تتساوى الأسهم من نفس النوع في الحقوق والمميزات أو القيود.
وفي هذه الحالة يجب أن يتضمن نظام الشركة منذ تأسيسها شروط وقواعد الأسهم الممتازة ونوع الامتياز المقرر لها وحدوده.$b$, E'\n', E'\r\n')),
    (10, 0, ARRAY['fb76970235d638a75fa23f5cb61568f3']::text[], ARRAY['fb89cf1488a95772d9d57ec8dfe3d80c']::text[], 'e4d4f48ebc396cbd7e9fdf5480959419', replace($b$لا يجوز تعديل الحقوق أو المميزات أو القيود المتعلقة بأي نوع من أنواع الأسهم إلا بقرار من الجمعية العامة غير العادية وبعد موافقة جمعية خاصة تضم حملة نوع الأسهم الذي يتعلق به التعديل بأغلبية الأصوات الممثلة لثلثي رأس المال الذي تمثله هذه الأسهم.
ويتم الدعوة لهذه الجمعية الخاصة على الوجه وطبقا للأوضاع التي تدعى إليها الجمعية العامة غير العادية.$b$, E'\n', E'\r\n')),
    (11, 0, ARRAY['e961fdc3a164670ce7abd6c92d878798']::text[], ARRAY['1661cb3003c1db004379475bfa67b327']::text[], '7bd057984b70d33cfc53b9c999ce2089', replace($b$مع عدم الإخلال بأوضاع الأسهم الممتازة وغيرها من الأسهم ذات الطبيعة الخاصة، تكون جميع حقوق والتزامات أصحاب الأسهم متساوية، ولا يلتزم المساهمون إلا بقيمة أسهمهم، كما لا يجوز - بأية حالة - زيادة التزاماتهم.$b$, E'\n', E'\r\n')),
    (12, 0, ARRAY['65851a12e9a0864f060c8acbb48732af']::text[], ARRAY['899ae4e8223a8a3e6f5edfb734d04046']::text[], '6c7e30a23dc72abe1b05c57d62a3e468', replace($b$ملغاة
*ملغاة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018 اعتبارا من تاريخ 17 يناير 2019.$b$, E'\n', E'\r\n')),
    (13, 0, ARRAY['28ac3c0f4f4e86a766887bef90ab5901']::text[], ARRAY['9cbe2dd41ebe3d1bb24f7ac27f7d358e']::text[], 'd1ac3eab66b471e343ff5541c9ae4d8d', replace($b$تصدر الصكوك وفقا للصيغ والشروط الواردة بأحكام القانون وهذه اللائحة.
وتصدر الصكوك من خلال شركة تصكيك تتلقى حصيلة الاكتتاب في الصكوك، وتعمل وكيلا عن مالكي الصكوك في متابعة استثمارها واستخدامها في الأغراض التي صدرت من أجلها، ومتابعة توزيع عوائد وقيمة استردادها، وتكون طرفا في جميع العقود مع الجهة المستفيدة من التمويل وغيرها من المشاركين في الإصدار نيابة عن مالكي الصكوك. ويضع مجلس إدارة الهيئة الشروط والضوابط الخاصة بقيام الجهة المستفيدة بإصدار الصكوك بذاتها لتمويل مشروعاتها.
*معدلة بقرار رئيس مجلس الوزراء رقم 1760 لسنة 2020.$b$, E'\n', E'\r\n')),
    (13, 1, ARRAY['7a91188d678f444f446b15dbd3bec1d3']::text[], ARRAY['448c1014113f6f379da1ca99fe7c5c64']::text[], '35d7df7e55f4a10c800b2dbc2b9eab56', replace($b$مع مراعاة المادة (14 مكررا "1") من القانون، تصدر الصكوك بموجب عقد اصدار وفقا لاحدي الصيغ الآتية:
1. صكوك الاستصناع : تصدر على أساس عقد الاستصناع ، وتستخدم حصيلة اصدارها لتمويل تصنيع أصل مبيع استصناعا لتسليمها الي مشتريها ، ويمثل الصك حصة شائعة في ملكية العين المصنعة ، وفي ثمنها بعد تسليمها لمشتريها ، وعائد هذه الصكوك هو الفرق بين تكلفة تصنيع العين وثمن بيعها.
2. صكوك الوكالة بالاستثمار : تصدر على أساس عقد الوكالة بالاستثمار ، وتحصيلة حصيلة اصدارها لدفع رأس مال الوكالة بالاستثمار الي الوكيل لاستثماره بأجرة معلومة ، ويمثل الصك حصة شائعة في ملكية موجودات الوكالة ، وتشمل الأعيان والمنافع والديون والنقود والحقوق المالية الأخري، وفي ثمنها بعد بيعها ، ويستحق مالكو صكوك الوكالة عائد استثمار موجودات ويتحملون مخاطر هذا الاستثمار، بنسبة ما يملكه كل منهم من صكوك ، ويستحق الوكيل أجرا معلوما مضمونا على مالكي الصكوك ، ويجوز أن يستحق مع الأجر حافزا هو كل أو بعض ما زاد من العائد عن حد معين ، مضمونا ، وتحدد نشره اكتتاب هذه الصكوك والعقود الشرعية الملحقة بها شروط وأحكام عقد الوكالة في الاستثمار وأجر الوكيل.
3. صكوك السلم : هي وثائق متساوية القيمة يتم اصدارها لتحصيل رأس مال السلم ، وتصبح سلعة السلم مملوكة لحملة الصكوك ، والسلم هو أن يتم تسليم رأس المال من قبل المشتري للبائع حين انعقاد العقد أو خلال ثلاثة أيام عمل تبدأ من تاريخ انعقاده وقبل تسليم السلعة ، على أن يتفقا على تسليمها في وقت محدد ( بيع آجل بعاجل ) ، ويتفقا على تحديد وصفها ، ونوعها ، وقدرها ، ومكان تسليمها>
4. صكوك المزارعة : تصدر على أساس عقد المزارعة ، وتستخدم حصيلة اصدارها لتمويل زراعة أرض يقدمها مالكها بناء على هذا العقد ويمثل الصك حصة شائعة في ملكية موجودات المزارعة غير الأرض، وفي الزرع بعد ظهوره، وفي ثمنه بعد بيعه، ويستحق مالكو الصكوك بصفتهم المزارعين بأموالهم، حصة معلومة من الزرع، ويستحق مالك الأرض الباقي ، وتحدد نشرة اكتتاب الصكوك والعقود الشرعية الملحقة بها شروط وأحكام عقد المزارعة،وحصة كل من مالكي الصكوك ومالك الأرض من ناتج البيع.
5. صكوك المسافاة : تصدر على أساس عقد المساقاة، وتستخدم حصيلة اصدارها لتمويل رعاية أشجار قابلة للاثمار وتعهدها بالسقي والتهذيب والتسميد ومعالجة الآفات حتي تثمر، ويمثل الصك حصة شائعة في ملكية موجودات المساقاة وفي الثمر بعد ظهروه، غير الأرض والشجر، ويستحق مالكو الصكوك حصة معلومة من الثمر ، ومن ثمنه بعد بيعه، ويستحق مالك الشجر الباقي وتحدد نشرة اكتتاب الصكوك والعقود الشرعية الملحقة بها شروط وأحكام عقد المساقاة، وحصة كل من مالكي الصكوك بوصفهم المساقين ومالك الشجر في الثمر.
*مضافة بقرار رئيس مجلس الوزراء رقم 1760 لسنة 2020.$b$, E'\n', E'\r\n')),
    (14, 0, ARRAY['bb63c6482caf5deabfe887dde7c44c28']::text[], ARRAY['bc4b7a4f35bdae040f5c7beed81e0422']::text[], '12faeaadfab40c1aff04211307dd2421', replace($b$تلتزم شركة التصكيك بالشروط الآتية:
1. أن يتضمن نظامها الأساسي إجازة إصدار الصكوك.
2. أن يكون رأسمالها المصدر مدفوعا بالكامل.
3. أن تحصل على تصنيف ائتماني لإصدار الصكوك من إحدى جهات التصنيف التي تقبل الهيئة تصنيفها لإصدارات الأوراق المالية الصادرة عنها والمعتمدة لدى الهيئة، وألا تقل درجة التصنيف عن المستوى الدال عن الوفاء بالالتزامات الواردة بنشرة الاكتتاب أو مذكرة المعلومات، وذلك في الحالات التي تتطلب طبيعتها ذلك.
4. أن تقوم بقيد الصكوك وإيداعها لدى شركة الإيداع والقيد المركزي وفقا لأحكام قانون الإيداع والقيد المركزي للأوراق المالية.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (15, 0, ARRAY['ef8c5cc10e2b1191f24136c8a52d3e83']::text[], ARRAY['3a781a924e970363fcb9fd888e1cf589']::text[], '2a4b67ae249303b38ba2fd74162d549d', replace($b$أحكام خاصة بإصدار الصكوك:
يجوز بموافقة الجمعية العامة غير العادية لشركة التصكيك إصدار صكوك قابلة للتحويل إلى أسهم، وذلك بناء على اقتراح مجلس إدارة الشركة، على أن يوضح به الغرض من الإصدار وقيمة العائد على الصك وأساس احتسابه ونوع الطرح وقابليتها للتحويل لأسهم وأسس التحويل، والتي تشمل:
معامل التحويل وطريقة احتسابه وتوقيت التحويل ومواعيد تقديم طلب التحويل وحدود حق الأسهم الناتجة عن التحويل في توزيعات الأرباح عن السنة المالية التي تم فيها التحويل، ويرفق به تقرير من مراقب حسابات الشركة بشروط الإصدار.وتصدر صكوك الإصدار الواحد بقيمة متساوية وقابلة للتداول وغير قابلة للتجزئة، وأن تعطي حقوق متساوية لمالكيها.
ويجوز لشركة التصكيك أن تصدر صكوك يطلق عليها متوافقة مع الشريعة الإسلامية أو إسلامية أو شرعية، على أن تتوافر الشروط الآتية:
(أ) أن يكون المشروع محل التصكيك مجازا من لجنة الرقابة الشرعية بما يفيد توافقه مع أحكام الشريعة الإسلامية. (ب) أن تكون جميع التعاقدات الخاصة بإصدار الصكوك ونشرات الطرح المرتبطة به مجازا من لجنة الرقابة الشرعية بما يفيد توافقها مع أحكام الشريعة الإسلامية.
(جـ) أن يكون طلب قيد وتداول إصدار الصكوك بإحدى البورصات مجازا من لجنة الرقابة الشرعية.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 0, ARRAY['8593f0e80ac8a4cb127496df86521ead']::text[], ARRAY['c54100578522de3fb027b7ef59340a6b']::text[], '5773f64090ed36afd947cb35d86201ce', replace($b$أحكام خاصة بطرح الصكوك:
تقوم الجهة المصدرة بطرح الصكوك بناء على نشرة اكتتاب عام معتمدة من الهيئة أو مذكرة معلومات تم الموافقة عليها من الهيئة، بحسب الأحوال، وذلك وفقا للنموذج المخصص لذلك، ويجوز للجهة إصدار برنامج إجمالى للصكوك يتم طرحه على عدة إصدارات وفقا للضوابط التى يصدرها مجلس إدارة الهيئة، على أن يتم تنفيذ البرنامج خلال ثلاث سنوات من تاريخ موافقة الهيئة على برنامج الإصدار أو خلال المدة التى يحددها قرار الهيئة أيهما أقل.
وتكون الجهة المصدرة مسئولة عن صحة المستندات والبيانات والإقرارات المقدمة للهيئة، وكذلك عن المعلومات الواردة في نشرة الاكتتاب العام أو مذكرة المعلومات ودقتها وشمولها، وأية معلومات أو بيانات أخرى يتم الإفصاح عنها، وتكون ذات علاقة بعملية الإصدار.
وتكون الصكوك مطروحة في اكتتاب عام إذا تم عرضها على أشخاص طبيعيين أو اعتباريين غير محددين سلفا. وتكون الصكوك مطروحة طرحا خاصا في حالة عرضها على أشخاص من ذوي الملاءة المالية أو مؤسسات مالية.
ويقصد بالأشخاص من ذوي الملاءة المالية:
• الأشخاص الاعتبارية العامة.
• صناديق التأمين والمعاشات العامة والخاصة.
• شركات الأموال التي لا يقل رأسمالها المدفوع عن مليون جنيه مصري.
• الأشخاص الطبيعيين ذوي الخبرة التي لا تقل عن ثلاث سنوات في أعمال الائتمان وإدارة الأموال والاستثمار.
• الأشخاص الطبيعيين المالكين لأوراق أو أدوات مالية تزيد قيمتها على خمسمائة ألف جنيه صادرة عن شركتين على الأقل.
ويقصد بالمؤسسات المالية:
• البنوك المصرية وفروع البنوك الأجنبية الخاضعة لإشراف البنك المركزي المصري.
• شركات التأمين أو إعادة التأمين.
• شركات رأس المال المخاطر.
• شركات الاستثمار المباشر
• شركات التمويل العقاري.شركات التأجير التمويلي
• شركات التخصيم.
• صناديق الاستثمار
• المؤسسات المالية الأجنبية.
ويجوز أن يكون للصكوك ضامن لتغطية الاكتتاب من الجهات المرخص لها بذلك من الهيئة، فإذا كان الضامن بنكا وجب عليه الحصول على موافقة البنك المركزي المصري، كما يجوز أن يكون للصكوك متعهد إعادة شراء أو متعهد استرداد من البنوك أو الشركات العاملة في مجال الأوراق المالية ويلتزم بشرائها أو استردادها وفقا لما تحدده نشرة الاكتتاب أو مذكرة المعلومات بحسب الأحوال.
ويجوز للجهة المستفيدة استرداد الصكوك قبل انتهاء مدتها، عن طريق تعهد شركة التصكيك ببيع موجوداتها للجهة بالثمن الوارد بالتعهد، إذا نصت نشرة الاكتتاب على ذلك.
*معدلة بموجب قرار رئيس مجلس الوزراء رقم 3045 لسنة 2023،
نص الفقرة قبل التعديل: تقوم الجهة المصدرة بطرح الصكوك بناء على نشرة اكتتاب عام معتمدة من الهيئة أو مذكرة معلومات تم الموافقة عليها من الهيئة، بحسب الأحوال، وذلك وفقا للنموذج المخصص لذلك.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 1, ARRAY['9dc6581d88bb2e37e75c8fb4cc9fe1b0']::text[], ARRAY['72c8d1c544153bdb149ae0466e6b41f1']::text[], '2d9ff225f974412bcb88d07e19e40385', replace($b$إجراءات إصدار وطرح الصكوك:
يقوم مجلس إدارة شركة التصكيك بتقديم طلب إلى الهيئة للحصول على موافقتها على إصدار الصكوك ويقدم الطلب موقعًا من قبل شخص مخول بالتوقيع نيابة عن مجلس إدارة شركة التصكيك، مرفقا به ما يأتى:
1. صورة من محضر اجتماع مجلس إدارة شركة التصكيك باقتراح إصدار الصكوك.
2. قرار الجمعية العامة غير العادية لشركة التصكيك بالموافقة على إصدار الصكوك، على أن تشمل الموافقة الدراسة التى أعدتها الشركة بشأن عملية الإصدار ، متضمنة الغرض من الإصدار وجدواه ، وأثر هذا الإصدار على حقوق حملة الأسهم إذا كانت الصكوك قابلة للتحويل إلى أسهم ، ونوع الطرح ونوع العائد وسعره وكيفية احتسابه ، ومدة الإصدار ، والبورصة التى تدرج الصكوك بها، وكيفية سداد قيمة استرداد الصكوك، وملخص التدفق النقدى السنوى المتوقع.
ويجب موافقة السلطة المختصة بالهيئات والأشخاص الاعتبارية العامة حال إصدارها صكوكا تكون هى الجهة المستفيدة منها.
3. آخر قوائم مالية سنوية لشركة التصكيك، والافتراضات الأساسية التى بنيت عليها تلك القوائم مرفقًا بها تقرير مراقب الحسابات.
4. آخر قوائم مالية سنوية للجهة الضامنة حال كون الإصدار مضمونا من قبل أى جهة غير حكومية.
5. نسخة من نشرة الاكتتاب أو مذكرة المعلومات، بحسب الأحوال، معتمدة من رئيس مجلس الإدارة والعضو المنتدب للشركة، مرفقا بها تقرير كل من مراقبى حسابات الشركة والمستشار القانونى لها برأيهم فى النشرة أو مذكرة المعلومات، على أن تكون مستوفاة لكافة توقيعات أطراف عملية الطرح.
6. بيان مصدق عليه من مراقب حسابات شركة التصكيك بموقف سداد إصدارات الصكوك السابقة حال وجودها. 7. موافقة البنك المركزى المصرى على الإصدار (بالنسبة للبنوك والمؤسسات المالية الأجنبية).
8. شهادة بالتصنيف الائتمانى للجهة المستفيدة والإصدار، من إحدى جهات التصنيف التى تقبل الهيئة التصنيف لإصدارات الأوراق المالية الصادرة عنها والمعتمدة لدى الهيئة، على أن يتم موافاة الهيئة بالشهادة المزمع إصدارها فور موافاتها بالمشروع النهائى لنشرة الاكتتاب أو مذكرة المعلومات، ويجب ألا تقل درجة التصنيف عن المستوى الدال على القدرة على الوفاء بالالتزامات التى ترتبها الصكوك وفقًا للقواعد التى يحددها مجلس إدارة الهيئة.
ويجوز إصدار الصكوك دون إعداد التصنيف الائتمانى للجهة المستفيدة والإصدار أو أحدهما فى الحالات ووفقًا للضوابط التى يصدر بها قرار من مجلس إدارة الهيئة
9. دراسة الجدوى للمشروع الذي يمول بحصيلة الاكتتاب والقيمة العادلة لموجودات الصكوك على أن تكون هذه الدراسة معتمدة من مستشار مالى مستقل معتمد لدى الهيئة.
10. عقود الإصدار وبيان شروط وأحكام كل منها، والآثار المترتبة عليها فى حال الصكوك المتوافقة مع الشريعة الإسلامية، وفتوى لجنة الرقابة الشرعية التى تفيد أن كل ما ورد بنشرة الاكتتاب أو مذكرة المعلومات وعقود الإصدار يتفق وأحكام الشريعة الإسلامية
11. بيان بالعقود المبرمة من شركة التصكيك والجهة المستفيدة.
12. بيان بالضمانات والتأمينات المقدمة من الشركة لأصحاب الصكوك.
13. بنود مصاريف الاكتتاب وكيفية احتسابها، مصدقا عليها من رئيس مجلس إدارة الجهة المستفيدة، ومرفقًا بها تقرير مراقب الحسابات.
14. بيان بالتأمين على أصول الجهة المستفيدة، على أن يتضمن قيمة التأمين ونوعه واسم الشركة المؤمن لديها وتاريخ انتهاء أو تجديد التأمين، والمستفيد من التأمين إن وجد.
15. بيان بالرهون والامتيازات الحالية المترتبة على أصول الجهة المستفيدة، على أن يتضمن بيان الأصل المرهون وقيمته ونوعه والتمويل الممنوح للجهة المستفيدة فى مقابله، ونوع الرهون والامتيازات المترتبة على الأصول (إن وجدت).
16. إقرار من شركة التصكيك والجهة المستفيدة فى بداية الإصدار أن جميع المعلومات الواردة بنشرة الاكتتاب أو مذكرة المعلومات صحيحة وعلى مسئوليتها وكذا المستندات والبيانات المرفقة بنشرة الاكتتاب أو مذكرة المعلومات.
17. إقرار من الشركة المستفيدة عند تقديم المستندات للهيئة بالالتزام بشراء موجودات الصكوك في نهاية أجل الصك أو قبل ذلك
18. إقرارات بالضمانات المقدمة من الجهة المستفيدة إلى مالكى الصكوك (إن وجدت) ونسخة من اتفاقية ضمان الصكوك (إن وجدت).
19. إقرار كل من منظم الإصدار والجهة المصدرة بأنه حصل على كافة البيانات والمعلومات اللازمة فى شأن الإصدار، وأنه بذل عناية الرجل الحريص للتأكد من أن المعلومات والبيانات المقدمة إلى الهيئة دقيقة وصحيحة وكاملة، والحفاظ على حقوق مالكى الصكوك المرتقبين.
20. إقرار بالالتزام بأحكام الشريعة الإسلامية طبقًا لما تقرره لجنة الرقابة الشرعية للإصدار فى حالة إصدار صكوك يطلق عليها متوافقة مع الشريعة الإسلامية.
ويجب على الهيئة إبداء الرأى فى الطلب المقدم خلال الخمسة عشر يوم عمل على الأكثر من تاريخ استلام الأوراق من الجهة المصدرة، ويكون إبداء الرأى إما بالموافقة للدعوة للاكتتاب العام أو الخاص والإذن بنشر الدعوة أو بالرفض المسبب، مع البيان الواضح للإجراءات والمستندات المطلوب استيفاؤها للحصول على الموافقة.
وفى حال رفض الهيئة للطلب، يجب أن يكون الرفض مرفقًا بخطاب رسمى يوضح الأسباب والإجراءات المكملة للحصول على الموافقة.
*معدلة بموجب قرار رئيس مجلس الوزراء رقم 3045 لسنة 2023،
نص المادة قبل التعديل:إجراءات إصدار وطرح الصكوك:يقوم مجلس إدارة شركة التصكيك بتقديم طلب إلى الهيئة للحصول على موافقتها على إصدار الصكوك.ويقدم الطلب موقعا من قبل شخص مخول بالتوقيع نيابة عن مجلس إدارة شركة التصكيك، مرفقا به ما يلي:
1. صورة من محضر اجتماع مجلس إدارة شركة التصكيك باقتراح إصدار الصكوك.
2. قرار الجمعية العامة غير العادية لشركة التصكيك بالموافقة على إصدار الصكوك، على أن تشمل الموافقة الدراسة التي أعدتها الشركة بشأن عملية الإصدار، متضمنة الغرض من الإصدار وجدواه، وأثر هذا الإصدار على حقوق حملة الأسهم إذا كانت الصكوك قابلة للتحويل إلى أسهم، ونوع الطرح ونوع العائد وسعره وكيفية احتسابه، ومدة الإصدار، والبورصة التي تدرج الصكوك بها، وكيفية سداد قيمة استرداد الصكوك، وملخص التدفق النقدي السنوي المتوقع.
ويجب موافقة السلطة المختصة بالهيئات والأشخاص الاعتبارية العامة حال إصدارها صكوكا تكون هي الجهة المستفيدة منها.
3. آخر قوائم مالية سنوية لشركة التصكيك، والافتراضات الأساسية التي بنيت عليها تلك القوائم، مرفقا بها تقرير مراقب الحسابات.
4. آخر قوائم مالية سنوية للجهة الضامنة حال كون الإصدار مضمونا من قبل أي جهة غير حكومية.
5. نسخة من نشرة الاكتتاب معتمدة من رئيس مجلس الإدارة والعضو المنتدبللشركة، مرفقا بها تقرير كل من مراقبي حسابات الشركة والمستشار القانوني لها برأيهم في النشرة، على أن تكون مستوفاة لكافة توقيعات أطراف عملية الطرح
6. بيان مصدق عليه من مراقب حسابات شركة التصكيك بموقف سداد إصدارات الصكوك السابقة حال وجودها.
7. موافقة البنك المركزي المصري على الإصدار (بالنسبة للبنوك والمؤسسات المالية الأجنبية).
8. شهادة بالتصنيف الائتماني لإصدار الصكوك من إحدى جهات التصنيف التي تقبل الهيئة التصنيف لإصدارات الأوراق المالية الصادرة عنها والمعتمدة لدى الهيئة، على أن يتم موافاة الهيئة بالشهادة المزمع إصدارها فور موافاتها بالمشروع النهائي لنشرة الاكتتاب ومذكرة المعلومات.
9. ويجب ألا تقل درجة التصنيف عن المستوى الدال على القدرة على الوفاء بالالتزامات التي ترتبها الصكوك وفقا للقواعد التي يحددها مجلس إدارة الهيئة.
10. دراسة الجدوى للمشروع الذي يمول بحصيلة الاكتتاب والقيمة العادلة لموجودات الصكوك على أن تكون هذه الدراسة معتمدة من مستشار مالي مستقل معتمد لدى الهيئة.
11. عقود الإصدار وبيان شروط وأحكام كل منها والآثار المترتبة عليها في حال الصكوك المتوافقة مع الشريعة الإسلامية، وفتوى لجنة الرقابة الشرعية التي تفيد أن كل ما ورد بنشرة الاكتتاب وعقود الإصدار يتفق وأحكام الشريعة الإسلامية
12. .بيان بالعقود المبرمة بين شركة التصكيك والجهة المستفيدة .بيان بالضمانات والتأمينات المقدمة من الشركة لأصحاب الصكوك.
13. بنود مصاريف الاكتتاب وكيفية احتسابها مصدقا عليه من رئيس مجلس إدارة الجهة المستفيدة ومرفقا بها تقرير مراقب الحسابات.
14. بيان بالتأمين على أصول الجهة المستفيدة، على أن يتضمن قيمة التأمين ونوعه واسم الشركة المؤمن لديها وتاريخ انتهاء أو تجديد التأمين، والمستفيد من التأمين إن وجد.
15. بيان بالرهون والامتيازات الحالية المترتبة على أصول الجهة المستفيدة، على أن يتضمن بيان الأصل المرهون وقيمته ونوعه والتمويل الممنوح للجهة المستفيدة في مقابله، ونوع الرهون والامتيازات المترتبة على الأصول (إن وجدت)
16. .إقرار من شركة التصكيك والجهة المستفيدة في بداية الإصدار أن جميع المعلومات الواردة بنشرة الاكتتاب صحيحة وعلى مسئوليتها وكذا المستندات والبيانات المرفقة بنشرة الاكتتاب.
17. إقرار من الشركة المستفيدة عند تقديم المستندات للهيئة بالالتزام بشراء موجودات الصكوك في نهاية أجل الصك أو قبل ذلك
18. .إقرارات بالضمانات المقدمة من الجهة المستفيدة إلى مالكي الصكوك (إن وجدت) ونسخة من اتفاقية ضمان الصكوك (إن وجدت).
19. إقرار كل من منظم الإصدار والجهة المصدرة بأنه حصل على كافة البيانات والمعلومات اللازمة في شأن الإصدار، وأنه بذل عناية الرجل الحريص للتأكد من أن المعلومات والبيانات المقدمة إلى الهيئة دقيقة وصحيحة وكاملة، والحفاظ على حقوق مالكي الصكوك المرتقبين.
20. إقرار بالالتزام بأحكام الشريعة الإسلامية طبقا لما تقرره لجنة الرقابة الشرعية للإصدار في حالة إصدار صكوك يطلق عليها متوافقة مع الشريعة الإسلامية.
ويجب على الهيئة إبداء الرأي في الطلب المقدم خلال خمسة عشر يوم عمل على الأكثر من تاريخ استلام الأوراق من الجهة المصدرة، ويكون إبداء الرأي إما بالموافقة للدعوة للاكتتاب والإذن بنشر الدعوة أو بالرفض المسبب، مع البيان الواضح للإجراءات والمستندات المطلوب استيفائها للحصول على الموافقة.
وفي حال رفض الهيئة للطلب، يجب أن يكون الرفض مرفقا بخطاب رسمي يوضح الأسباب والإجراءات المكملة للحصول على الموافقة.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 2, ARRAY['6e0d3037f50d4de5ad5723598f7bef5f']::text[], ARRAY['5b622bf51e1582223550df50d975caf0']::text[], '3b6abf22afbbea202e08c7b7e736b89a', replace($b$البيانات التى يجب ان تتضمنها نشرة الاكتتاب او مذكرة المعلومات لاصدار الصكوك:
يجب ان تتضمن نشرة الاكتتاب او مذكرة المعلومات البيانات الاتية:
1. بيانات شركة التصكيك:
البيانات الرئيسية للشركة وتشمل اسم الشركة وتشمل ورأس مالها وغرضها واصدارات الصكوك السابقة.
حقوق الشركة والتزاماتها منذ اصدار الصك وحتى نهاية اجله.
التزامات الشركة مع أطراف عملية التصكيك.
2. بيانات الجهة المستفيدة:
اسم الجهة المستفيدة وغرضها ورأس مالها واصدارات الصكوك او السندات السابقة.
بيان بالمساهمين الرئيسيين فيها وعنوان مركزها الرئيسى وتاريخ تأسيسها واسم وعنوان مراقبى حساباتها.
البيانات الخاصة باعضاء مجلس ادارة الشركة ومديريها.
القوائم المالية المستفيدة عن ثلاث سنوات سابقة مرفقا بها تقارير مراقبى الحسابات.
توقعات الاداء المالى للجهة المستفيدة خلال مدة الاصدار ويجب ان تضمن نشرة الاكتتاب تقديرات الاداء المالى عن الفترة المستقبلية التى تمثل فترة الاصدار.
بيان عن الدعاوى القضائية المقامة ضد الجهة المستفيدة حال وجودها.
3. بيانات عن لجنة الرقابة الشرعية (حال كون الصكوك متوافقة مع الشريعة الاسلامية):
معلومات تعريفية عن لجنة الرقابة الشرعية التى اجازت الصكوك وتشمل التفاصيل الخاصة بعدد اعضاء اللجنة واسمائهم وخبراتهم بما يتفق مع الضوابط الصادرة بقرار مجلس ادارة الهيئة.
4. بيانات متعلقة بالصكوك:
شروط واحكام الاصدار بما فى ذلك القيمة الاجمالية للاصدار وقيمة الصكوك لاسمية وعددها وملخصا بالحقوق التى تمنحها الصكوك لمالكيها وسعر الاصدار وبيانا بقيمة الربح المتوقع وتفاصيل خاصة باجراءات الاستهلاك او الاستيرداد المبكر وبيان باجراءات تداول وتسوية الصكوك واستردادها، وتتضمن المعلومات على وجه الاخص ما يأتي:
تاريخ الاستحقاق النهائى، واجراءاته.
الضمانات المقدمة حال وجودها، على ان يبين نوع الضمان ونسبة التغطية لاجمالى قيمة الصكوك، والجهة الضامنة.
اوجه استخدام حصيلة الاكتتاب فى الصكوك.
معدل التحويل إذا كانت الصكوك قابلة للتحويل لاسهم .اذا كانت الصكوك قابلة للتحويل الى اسهم وجب ان تحتوى نشرة الاكتتاب على الاجراءات الخاصة بعملية وشروط التحويل، وايضاح جميع القواعد والاجراءات التى يجب اتباعها للتحويل لاسهم وعلى وجه الخصوص معامل التحويل، والحقوق ثايتا او متغيرا خلال مدة اجل الاصدار، واذا كان متغيرا وجب تقديم جدول محدد بذلك ويعلن عنه فى النشرة.
الضوابط الحاكمة لتداول واسترداد الصكوك محل الاصدار، بحسب طبيعة ونوعية كل صك، وفقا لاحكام عقد الاصدار. الاسباب التى تستوجب الاستحقاق المبكر ومعالجة التعثر فى حالة وقوعه ، وكيفية تسوية حقوق مالكى الصكوك. الافصاح عن عوامل المخاطر التى تخص الاستثمار فى الصكوك، وكذلك المخاطر المتعلقة بالجهة المستفيدة وبمجال نشاطها وبالمشروع او النشاط الذى يراد تمويله بالصكوك، وذلك فى قسم يحمل عنوان ( عوامل المخاطر ) بترتيب اولوية المخاطر من الاكثر الى الاقل خطرا، وايضا بيان طرق التحوط من هذه المخاطر.
اذا كان الاصدار مضمونا من قبل شركة يجب ان تتضمن النشرة معلومات متكاملة عن الشركة الضامنة، فاذا كانت الجهة الضامنة للاصدار، جهة حكومية، يجب ذكر اسم الجهة الحكومية الضامنة او القرار الذى تم بموجبه منح الضمان. اذا كانت الصكوك مضمونة بموجودات وجب ان تحتوى نشرة الاكتتاب على شرح بالتزامات الجهة المصدرة تجاه مالكى الصكوك والتفاصيل بالاجراءات الخاصة بالبيع والتنازل عن الموجودات او عن اى حقوق للجهة المصدرة فى الموجودات وطبيعة الموجودات وملخص لشروط واحكام اى عقود او اتفاقيات او ضمانات او كفالات بنكية مرتبطة بالموجودات وتاريخ او تواريخ استحقاق الموجودات وعملة وقيمة الموجودات الدفترية والفعلية واذا كانت الموجودات مضمونة بموجودات اخرى تحدد تفاصيل تلك الموجودات الاخرى. وفى حالة اصدار صكوك يطلق عليها متوافقة مع الشريعة الاسلامية ، فيجب ان تتضمن نشرة الاكتتاب او مذكرة المعلومات تفاصيل القرارات او التصاريح او الموافقات التى بموجبها اصدرت الصكوك وتفاصيل اى ديون او صكوك تكون لها اولوية الدفع قبل صكوك محل الاصدار المعنى، وعلى الاخص ما يأتي:
عقود الاصدار وبيان شروط واحكام كل منها والاثار المترتبة عليها.
بيان بالعقود الموقعة بين الجهة المستفيدة والمشاركين فى الإصدار.
اية اقرارات او التزامات بين اطراف عملية التصكيك.
5. وصف للمشروع محل التمويل بحصيلة اصدار الصكوك:
دراسة جدوى المشروع او النشاط الذي يمول بحصيلة الصكوك والتى تتضمن:
وصفا كافيا للمشروع او النشاط
تحديد تكاليف انشائه او تطويره.
ادارة المشروع ومكوناته ومراحل تنفيذه حسب ما يتم الاكتتاب فيه.
سابقة الخبرات فى ادارة تلك المشروعات.
تفاصيل الاقتراضات الاساسية التى تستند اليها التوقعات.
معدل العائد، وطريقة الاحتساب.
طريقة توزيع الارباح المتوقعة للمشروع او النشاط.
6. بيانات الاكتتاب:
القيمة الاسمية للصك، وطبيعة الاكتتاب وعملته وسعر الاكتتاب، ومدته، والقيمة الاجمالية له.
بيان الشرائح المخصصة للافراد والمؤسسات (ان وجد).
بيان المستندات والاجراءات المطلوبة من المكتتبين عند تقديم طلب الاكتتاب وكيفية الحصول على نشرة الاكتتاب او مذكرة المعلومات.
تفاصيل الحد الادنى والحد الاقصى للاكتتاب.
اسلوب تخصيص الصكوك المصدرة بين حالة زيادة قيمة الاكتتاب عن قيمة الاصدار.
طريقة سداد قيمة الاكتتاب، ومتلقى الاكتتاب، وبيان التاريخ المتوقع لقيد الصكوك ( ان وجد ).
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 3, ARRAY['8319fae07322b8f7994d6ae02e2766de']::text[], ARRAY['f55ed3cfb9b3f66d501a2f3f8e5c9014']::text[], '4a7850b3998b4bf9621ca9ea0b1cf6fc', replace($b$متطلبات الإفصاح للجهة المستفيدة:
تلتزم الجهة المستفيدة بإخطار الهيئة بما يأتى:
1. ما يفيد نشر ملخص وافٍ لتقرير مجلس الإدارة وللقوائم المالية السنوية وربع السنوية والإيضاحات المتممة لها وفقًا لمعايير المحاسبة التى يحددها مجلس الإدارة ووفقًا لمعايير المراجعة المصرية.
2. أى تعديلات على التعاقدات والتعهدات بنشرة الاكتتاب أو مذكرة المعلومات لإصدار الصكوك.
3. أى واقعة أو معلومة يترتب عليها معلومات جوهرية من شأنها أن تؤثر على تداول الصكوك أو على سعرها أو على مقدرة الجهة المستفيدة على الوفاء بالتزاماتها وذلك فور علم تلك الجهة بتلك الواقعة أو المعلومات 4. الأحكام القضائية أو أحكام التحكيم الصادرة فى أى مرحلة من مراحل التقاضى والتى تؤثر فى مركز الشركة المالى أو فى حقوق مالكى الصكوك أو على القرار الاستثمارى للمتعاملين.
5. القرارات الجوهرية التى تصدر عن جماعة مالكى الصكوك وأى تعديلات فى بيانات نشرة الاكتتاب أو مذكرة المعلومات.
6. شهادة حديثة بالتصنيف الائتمانى تقدم خلال تسعين يوما من نهاية السنة المالية وتجدد سنويا خلال أجل الصك، بمراعاة أحكام المادة (16 مكررًا) من هذه اللائحة.
7. القرارات الصادرة بعدم سداد أى جزء من الربح المستحق لمالكى الصكوك.
8. أى إصدار جديد لأسهم أو سندات دين أو صكوك تقرر الجهة المصدرة القيام به وعلى الأخص أية ضمانة متعلقة بهذا الإصدار الجديد.
9. أى تغيير يطرأ على مستندات التأسيس للجهة المستفيدة.
10. أى تغيير بالنسبة لرأس المال المصدر أو المرخص به للجهة المستفيدة.
11. أى قرار بتغيير طبيعة غرض ونشاط الجهة المستفيدة.
12. أى تغيير فى عضوية مجلس إدارة الجهة المستفيدة
13. أى تغيير فى مراقبى حساباتها.
14. أى تغيير فى هيكل الملكية يترتب عليه تملك شخص بمفرده أو مع مجموعته المرتبطة لنسبة (5%) أو أكثر من أسهم الشركة أو حقوق التصويت بها.
15. حالات تعارض المصالح وأوجه تجنبها.
وفى حال كون الصكوك مطروحة فى اكتتاب أو طرح عام أو مقيدة بإحدى البورصات المصرية ، فيجب إخطار الهيئة والبورصة بالأمور التالية فور وقوعها أو علمها بها:
أ. قيام الجهة المستفيدة أو شركتها الأم أو أى من شركاتها التابعة بتقديم طلب بشأن حلها أو بشأن تعيين مصف لها.
ب. صدور حكم بحل أو تصفية الجهة المستفيدة أو شركتها الأم أو أية شركة تابعة لها
ج. اتخاذ الجهة المستفيدة أو شركتها الأم أو أية شركة تابعة لها قرارا بحلها.
د. انقضاء أجل الجهة المستفيدة أو شركتها الأم أو أى من شركاتها التابعة.
ه. قيام أى مرتهن بحيازة أو وضع اليد أو بيع جزء من موجودات الجهة المستفيدة تزيد قيمته الإجمالية على (10%) من القيمة الدفترية لصافى تلك الموجودات.
وذلك دون الإخلال بأى التزام بمتطلبات الإفصاح الواردة بقواعد قيد وشطب الأوراق المالية للصكوك المقيدة بجداول البورصة.
*معدلة بموجب قرار رئيس مجلس الوزراء رقم 3045 لسنة 2023، نص المادة قبل التعديل:
متطلبات الافصاح للجهة المستفيدة:
تلتزم الجهة المستفيدة باخطار الهيئة بما يأتى:
1. نشر ملخص واف لتقرير مجلس الادارة وللقوائم المالية السنوية وربع السنوية والايضاحات المتممة لها وفقا لمعايير المحاسبة التى يحددها مجلس الادارة ووفقا لمعايير المراجعة المصرية.
2. اى تعديلات على التعاقدات والتعهدات بنشرة الاكتتاب او مذكرة المعلومات لاصدار الصكوك.
3. اى واقعة او معلومة يترتب عليها معلومات جوهرية من شأنها ان تؤثر على تداول الصكوك او على سعرها او على مقدرة الجهة المستفيدة على الوفاء بالتزاماتها وذلك فورعلم تلك الجهة بتلك الواقعة او المعلومات.
4. الاحكام القضائية او احكام التحكيم الصادرة فى اى مرحلة من مراحل التقاضى والتى تؤثر فى مركز الشركة المالى ا وفى حقوق مالكى الصكوك او على القرار الاستثمارى للمتعاملين.
5. القرارات الجوهرية التى تصدر عن جماعة مالكى الصكوك واى تعديلات فى بيانات نشرة الاكتتاب.
6. شهادة حديثة بالتصنيف الائتمانى تقدم خلال تسعين يوما من نهاية السنة المالية وتجدد سنويا خلال اجل الصك. 7. القرارات الصادرة بعدم سداد اى جزء من الربح المستحق لمالكى الصكوك.
8. اى اصدار جديد لاسهم او سندات دين او صكوك تقرر الجهة المصدرة القيام به وعلى الاخص اى ضمانة متعلقة بهذا الاصدار الجديد.
9. اى تغيير يطرا على مستندات التأسيس للجهة المستفيدة.
10. اى تغيير بالنسبة لرأس مال المصدر او المرخص به للجهة المستفيدة.
11. اى قرار بتغيير طبيعة غرض ونشاط الجهة المستفيدة.
12. اى تغيير فى عضوية مجلس ادارة الجهة المستفيدة او مديريها.
13. اى تغيير فى مراقبى حساباتها.
14. اى تغيير فى هيكل الملكية.
15. حالات تعارض المصالح وأوجه تجنبها.
كما يجب اخطار الهيئة والبورصة ، حال كون الصكوك مطروحة فى اكتتاب عام للتداول ، بالامور التالية فور وقوعها او عملها بها:
( أ ) قيام الجهة المستفيدة او شركتها الام او اى من شركاتها التابعة بتقديم طلب بشأن حلها او بشأن تعيين مصف لها.
( ب ) صدور حكم بحل او تصفية الجهة المستفيدة او شركتها الام او اية شركة تابعة لها.
( ج ) اتخاذ الجهة المستفيدة او شركتها الام او اية شركة تابعة لها قرارا بحلها.
( د ) انقضاء اجل الجهة المستفيدة او شركتها الام او اى من شركاتها التابعة.
( هـ ) قيام اى مرتهن بحيازة او وضع اليد او بيع جزء من موجودات الجهة المستفيدة تزيد قيمته الاجمالية على (10%) من القيمة الدفترية لصافى تلك الموجودات.
وذلك دون الاخلال باى التزام بمتطلبات الافصاح الواردة بقواعد قيد وشطب الاوراق المالية للصكوك المقيدة بجداول البورصة.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 4, ARRAY['9f602833e491c313a539c4d7fe3fde2b']::text[], ARRAY['fa79421ae71d6a71edfa058c97d19b7c']::text[], '39ae982b4a3cf38440ef9200e34a7c4b', replace($b$التزامات الافصاح لشركة التصكيك:
تلتزم شركة التصكيك باخطار الهيئة بما ياتى:
اى تغيير فى اطراف عملية التصكيك او فى اى بند من بنود عقد الاصدار.
تقرير ربع سنوى عن متابعة الاستثمارات واستخدامها فى الاغراض التى صدرت من اجلها.
تواريخ توزيع عائد الصكوك.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 5, ARRAY['41d66b83266c61023955525e11515f05']::text[], ARRAY['0fab19a930ebbe41e31550ba121e042f']::text[], '3db31e50a7a07efbe5dd5957849afcad', replace($b$التزامات الإفصاح لوكيل السداد:
يجب أن يُعد وكيل السداد تقريرًا شهريًا بشأن عائد المشروعات المستثمر بها الصكوك وعليه إخطار الهيئة وحملة الصكوك أو من يمثلهم بالتقرير مرفقًا به تقرير مراقب الحسابات.
ويجب أن يتضمن التقرير الشهرى ما يأتى:
(أ) العوائد التى تم تحقيقها والمُحصل منها فى الفترة المُعد عنها التقرير.
(ب) ما تم سداده من مستحقات حملة الصكوك.
(ج) العمولات والمصروفات التى تم خصمها.
(د) فائض الأموال المودعة لديه ومجالات استثماره وفقًا لنشرة الاكتتاب
أو مذكرة المعلومات.
(ه) حالات التأخير أو الامتناع عن السداد والإجراءات التى تمت بشأنها.
(و) كل ما يؤثر على حقوق حملة الصكوك تأثيرًا جوهريًا.
(ز) أى تغيير بشأن الاتفاق مع وكيل السداد أو أطراف عملية التصكيك.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018 ومعدل بقرار رئيس مجلس الوزراء رقم 2423 لسنة 2024.$b$, E'\n', E'\r\n')),
    (16, 6, ARRAY['621317c0cf96b19f92418d60519b9338']::text[], ARRAY['2f71c8753af4e3be3d659ab6787c51ab']::text[], 'ff47e755e12f6e8c1c89447982f19eea', replace($b$التزامات لجنة الرقابة الشرعية (حال اصدار الصكوك متوافقة مع الشريعة الاسلامية):
الالتزام باعداد تقارير دورية كل ثلاثة اشهر من تاريخ اصدار الصك وحتى تمام سداده.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 7, ARRAY['fdf1f17f533c86ea15f063882c37a26d']::text[], ARRAY['d6766d3cb91ac532b88bc8e647103bc5']::text[], '8ef9f27d37f9117f77dac5cb600d6912', replace($b$يجب ان يتم قيد الصكوك وايداعها لدى شركة الايداع والقيد المركزي وفقا لأحكام قانون الايداع والقيد المركزى.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 8, ARRAY['7120502e7364fec0ea3ee81a5b1618d2']::text[], ARRAY['1606762f6fe96b8bdbc6f13c57d0c0d8']::text[], '78d886646b50b1ef269e02978afd246d', replace($b$يحدد مجلس ادارة الهيئة شروط وقواعد قيد الصكوك فى احدى بورصات الاوراق المالية المصرية او احدى البورصات بالخارج بعد موافقة الهيئة.
ويكون تداول الصكوك خارج بورصات الاوراق المالية وفقا للضوابط التى يصدر بها قرار من مجلس ادارة الهيئة.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 9, ARRAY['13b317ef70f54ab78dc2c415fbfd1cf0']::text[], ARRAY['e9464d936f9f5641af8ffd289130cbed']::text[], '8ee164e145f85ae5c08a88bf9a72c036', replace($b$يصدر مجلس ادارة الهيئة معايير المحاسبة والمراجعة التى تلتزم بها الشركات المصدرة للصكوك والشركات المستفيدة مراجعة حساباتهم، وله ان يعتمد اى معايير محاسبة ومراجعة اخرى صادرة من احدى الجهات الدولية ذات الاختصاص.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (16, 10, ARRAY['8b2ebe825ec4c71363e3484177fee815']::text[], ARRAY['6b7e19ff52377f331697c68e95fed324']::text[], '50927663227c55289ca2f65bb8ffaa29', replace($b$تلتزم الجهة المستفيدة باداء ناتج قيمة الصكوك فى نهاية اجلها لمالكيها وتتعهد بشراء موجوداتها القائمة فى نهاية مدة الصكوك.
ويجوز التعهد بشراء الموجودات قبل نهاية مدة الصكوك وتحدد هذه القيمة وفقا للضوابط التى تتضمنها نشرة الاكتتاب.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (17, 0, ARRAY['8f99a9d68ccedab7dd1ca693639be506']::text[], ARRAY['5d78dacada3cc9e6f2cdaccfd5ce258f']::text[], '96de0d9c5e6167e1c61ca76d199ecde1', replace($b$تكون زيادة رأس المال بإصدار أسهم جديدة، على أن تحدد لهذه الأسهم قيمة عادلة وقت الإصدار طبقاً لما يلي:
أولًا: بالنسبة للشركات التي طرحت أسهما لها في اكتتاب عام، والشركات المقيدة لها أسهم بالبورصة، والبنوك وشركات التأمين، والشركات المشار إليها في البند (ب) من المادة (27) من القانون، تحدد القيمة العادلة لأسهم الزيادة فيها بناء على تقرير من أحد المستشارين الماليين المعتمدين لدى الهيئة على أن يكون هذا المستشار المالي مستقلًا عن الشركة والأشخاص المرتبطة بها وأعضاء مجالس إدارتها ومراقبي حساباتهم ولا تربطه بهم أية مصالح مشتركة.
ويصدر تقرير التقييم طبقاً للأصول المتعارف عليها في هذا الشأن، وتحت مسئولية الشركة، ويحدد التقرير أسس التقييم التي تم الاعتماد عليها.
ثانياً: بالنسبة للشركات غير المشار إليها في البند السابق، يكون تحديد القيمة العادلة لأسهم الزيادة فيها إما وفقا لأحكام البند السابق، أو وفقا لدراسة تعدها الشركة لهذا الغرض وتحت مسئوليتها ومرفقا بها تقرير مراقب حسابات الشركة، بمراعاة معايير المراجعة المصرية.
وفي جميع الأحوال تعتمد السلطة المختصة بالشركة القيمة التي تصدر لها أسهم الزيادة بما لا يجاوز القيمة العادلة ما لم يوافق جميع المساهمين على غير ذلك إذا كان الاكتتاب في الزيادة مقصوراً على قدامى المساهمين على أنه في حالة طرح أسهم الزيادة مع تنازل قدامى المساهمين عن حقوق الأولوية يجب أن تصدر الأسهم بما لا يقل عن القيمة العادلة. وفي جميع الأحوال يحب عند زيادة رأس المال طبقاً لهذه المادة مراعاة ما يلي:
أ. إذا كانت القيمة المحددة أزيد من القيمة الاسمية للسهم تجنب الزيادة في حساب احتياطي.
ب. إذا كانت القيمة المحددة أقل من القيمة الاسمية للسهم تعين على الشركة تخفيض القيمة الاسمية للأسهم القائمة إلى القيمة المحددة وحساب رأس المال وفقاً لذلك.
ج. إذا كانت القيمة المحددة أقل من الحد الأدنى للقيمة الاسمية للسهم المقرر قانوناً يتعين حساب قيمة الأسهم بما فيها الأسهم القائمة بالحد الأدنى مع تخفيض عدد أسهم الشركة وحساب رأس المال وتبعاً لذلك.
وفي حالة زيادة رأس المال عن طريق إصدار أسهم مجانية لتوزيعها على جميع المساهمين تطبق القواعد والإجراءات الواردة بالمادة (23) من هذه اللائحة.
د. يلتزم مجلس إدارة الشركة بالإفصاح مسبقاً عن أوجه استخدام أو استثمار الأموال المتحصلة من زيادة رأس المال.
*معدلة بقرار وزير الإستثمار رقم 45 لسنة 2015.$b$, E'\n', E'\r\n')),
    (17, 1, ARRAY['866ce8ed0bfc241aecdc15b8979cc34f']::text[], ARRAY['94be157384a5bce9513aa26f6cfeb50f']::text[], 'cf293102fb1c3b1f5c23f2216faaf649', replace($b$في حالة إصدار سندات أو صكوك تمويل أو غيرها من الأوراق المالية القابلة للتحويل لأسهم، يجب أن يتضمن قرار الجمعية العامة غير العادية - المتضمن الموافقة على إصدار هذه الأوراق المالية - معامل التحويل المستخدم أو أسلوب تحديد قيمة سهم الشركة في تاريخ التحويل طبقاً للدراسة التي تعدها إدارة الشركة في هذا الشأن، وذلك كله دون التقيد بقواعد تحديد قيمة الأسهم الواردة بالمادة السابقة عند حلول أجل تحويل الأوراق المالية المشار إليها لأسهم.
*مضافة بقرار وزير الاستثمار والتعاون الدولي رقم 45 لسنة 2015.$b$, E'\n', E'\r\n')),
    (18, 0, ARRAY['f312224d8e95d1f7ab50ea157b5a73b4']::text[], ARRAY['a2c72421094300a2ae02fa79ca7d1fa9']::text[], '0916a4af4628918e921d4e39bdc6637b', replace($b$يجوز بقرار من الجمعية العامة غير العادية زيادة رأس المال المرخص به، وتتم الزيادة بناء على اقتراح مجلس الإدارة أو الشريك أو الشركاء المديرين في شركات التوصية بالأسهم.$b$, E'\n', E'\r\n')),
    (19, 0, ARRAY['c5e34ceeb3b91922cca87e80e9ce224f']::text[], ARRAY['d328a664600031ce2ad477a6bc1cefbe']::text[], '303062b2a25ac4362913c24ee4ced725', replace($b$يجب على مجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال أن يضمنوا اقتراحهم بزيادة رأس المال المرخص به جميع البيانات المتعلقة بالأسباب التي تدعو إلى الزيادة، وأن يرفقوا به تقريرا بسير الأعمال بالشركة خلال السنة التي تم فيها تقديم الاقتراح بالزيادة وميزانية السنة التي تسبقها في حالة اعتمادها.
ويرفق بتقرير مجلس الإدارة تقرير آخر من مراقب الحسابات بشأن مدى صحة البيانات المالية الواردة في تقرير مجلس الإدارة.$b$, E'\n', E'\r\n')),
    (20, 0, ARRAY['ee38933c08adce9a45a721b91087ef3f']::text[], ARRAY['91df647340c1b2a5bb1b6a65448f8f57']::text[], '5ecb393c7ba4778650ec75a1f4473cb0', replace($b$يجوز بقرار من مجلس الإدارة أو بقرار من الشريك أو الشركاء المديرين بحسب الأحوال زيادة رأس المال المصدر في حدود رأس المال المرخص به.
ويشترط لصحة القرار الصادر بالزيادة تمام سداد رأس المال المصدر بالكامل، ومع ذلك يجوز بقرار من رئيس الهيئة السماح للشركات المساهمة العاملة في أحد مجالات السياحة أو الإسكان أو الإنتاج الصناعي أو الزراعي، بزيادة رأس مالها، سواء بحصص أو أسهم نقدية أو مقابل حصة عينية قبل تمام سداد رأس المال المصدر.$b$, E'\n', E'\r\n')),
    (21, 0, ARRAY['8e57831744e2dba8fd20d7f3e605c295']::text[], ARRAY['7f16a47d1e0185daffb3a2d3c6d75804']::text[], 'fd50dcb17f08556a181f4b9e413aee39', replace($b$يجب أن تتم زيادة رأس المال المصدر خلال الثلاث سنوات التالية لصدور قرار الزيادة وإلا كانت باطلة، ما لم يصدر قرار جديد في هذا الشأن، ويستثنى من ذلك حالة زيادة رأس المال الناتجة عن تحويل السندات أو صكوك التمويل وغيرها من الأوراق المالية إلى أسهم، إذا كان في شروط إصدارها أن لحامليها الحق في طلب تحويلها إلى أسهم.$b$, E'\n', E'\r\n')),
    (22, 0, ARRAY['8cec730ae63ce6209989cec2f482c8ba']::text[], ARRAY['f8f8a4fa95334a7a365e6f0ec4ccd723']::text[], 'd23beb2af623d8f1f1b9b6cb685b9728', replace($b$يجوز ان يكون مقابل أسهم الزيادة ما يأتى:
أ. مبالغ نقدية.
ب. حصص عينية.
ج. ديون نقدية مستحقة الاداء للمكتتبين قبل الشركة.
د. تحويل ما يملكه المكتتب من سندات او صكوك التمويل الى أسهم وذلك بحسب شروط اصدار تلك السندات او هذه الصكوك.
ه. تحويل ما يملكه المكتتب من حصص تأسيس او حصص أرباح الى اسهم وذلك على سبيل التعويض المنصوص عليه فى المادة (34) من القانون رقم 159 لسنة 1981 المشار اليه.
و. مبادلة الأسهم التي يمتلكها المكتتب في رأس مال شركة أخرى بقصد الاستحواذ أو الاندماج.
ويقصد بمبادلة الاسهم ان يتنازل حملة أسهم احدى الشركات التى ترغب الشركة فى الاستحواذ على اسهمهم فيها مقابل حصولهم على أسهم فى زيادة رأس مال الشركة المستحوذة وتتم عملية مبادلة الاسهم وفقا للضوابط الاتية:
1. ان يكون الهدف من عملية تبادل الاسهم هو الاستحواذ او الاندماج.
2. ان تتم عملية التنازل عن الاسهم من خلال عملية طرح خاص.
3. ان تتحدد قيمة الاسهم المقدمة من المكتتبين على اساس نصيب السهم فى القيمة العادلة لكافة أصول الشركة حسبما تحددها الشركة ويقر بصحتها مراقب الحسابات.
*معدلة بقرار وزير الإستثمار رقم 12 لسنة 2007.$b$, E'\n', E'\r\n')),
    (23, 0, ARRAY['e57902a07c0d5476a6d319d2371fd03f']::text[], ARRAY['4527a963a3f539de242a185e1fd33fde']::text[], 'bc146efcb75ddfb81b5ebf408fd0fab0', replace($b$يجوز بقرار من الجمعية العامة للشركة بناء على اقتراح مجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال، أن تقرر تحويل المال الاحتياطي أو جزء منه إلى أسهم يزاد بقيمتها رأس المال المصدر.
وتوزع الأسهم الناتجة عن الزيادة مجانا على المساهمين أو الشركاء الحاليين للشركة كل بحسب قيمة مساهمته أو مشاركته.$b$, E'\n', E'\r\n')),
    (24, 0, ARRAY['bc5bb52caf9aafde6d8dc89a37a502b5']::text[], ARRAY['5192d1c5c416fb2cdbe6805973ee6373']::text[], '9ced74488c66f5252efa9861d5f7eb9f', replace($b$لا يجوز زيادة رأس المال المصدر بأسهم ممتازة، إلا بعد موافقة الجمعية العامة غير العادية بأغلبية ثلاثة أرباع أسهم الشركة قبل الزيادة وتعديل النظام الأساسي للشركة، وذلك بناء على اقتراح مجلس الإدارة وتقرير من مراقب الحسابات في شأن الأسباب المبررة لذلك.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (25, 0, ARRAY['b5eebcb1fb97ba87dae7bb1f571a473f']::text[], ARRAY['9070fac7a4179b66b8e04f3c63092967']::text[], '8122ce3dd350130cc3affd6124e7f718', replace($b$يثبت الاكتتاب في أسهم الزيادة بموجب شهادة اكتتاب يبين فيها تاريخ الاكتتاب واسم المكتتب في الأسهم الاسمية وجنسيته وعنوانه وعدد الأسهم مدونا بالأحرف والأرقام الحسابية وتوقيع المكتتب أو من ينوب عنه، بالإضافة إلى البيانات المنصوص عليها في المادة (33) من هذه اللائحة عدا ما ورد بالبندين (3، 4) منها، ويعطي المكتتب صورة من شهادة الاكتتاب.
ويتبع في شأن تخصيص الأسهم وإثبات عدد الأسهم المخصصة للمكتتب في تلك الشهادة ما نصت عليه المادة (54) من هذه اللائحة.$b$, E'\n', E'\r\n')),
    (26, 0, ARRAY['84d3fa319766874cf4d1161151ccbf6b']::text[], ARRAY['932aeb0c0d9017d77e8158bf30ef2572']::text[], '4bb107ef529f15cd20af65ddda4c1a30', replace($b$يجوز أن يتم الاكتتاب في أسهم الزيادة بطريق المقاصة بين حقوق المكتتب النقدية المستحقة الأداء قبل الشركة، وبين قيمة الأسهم المكتتب فيها، كلها أو بعضها، وذلك بإقرار يصدر من مجلس الإدارة أو من يفوضه بقيمة هذه الديون، ويصدق عليه من قبل مراقب الحسابات، ويقدم هذا الإقرار إلى الجهة التي تتلقى الاكتتاب لإرفاقه بأصل شهادة الاكتتاب.$b$, E'\n', E'\r\n')),
    (27, 0, ARRAY['cea5ba8dafd73335600ab8dbc523b4c1']::text[], ARRAY['562ba9f249582405b79781f802b5d331']::text[], '62cce8feee6fff4c3cce0ca46b6d3f1d', replace($b$إذا تم طرح أسهم الزيادة أو جانب منها في اكتتاب عام أو خاص فيجب أن يكون ذلك بناء على نشرة اكتتاب تتوافر فيها الشروط الواردة بالقانون وبهذه اللائحة.
ويجب أن يتم الاكتتاب عن طريق أحد البنوك المرخص لها بقرار من الوزير بتلقي الاكتتابات أو عن طريق الشركات التي تنشأ لهذا الغرض أو الشركات التي يرخص لها بالتعامل في الأوراق المالية بعد موافقة الهيئة.
وبالنسبة للشركات التي تم إيداع أسهمها طبقا لأحكام قانون الإيداع والقيد المركزي للأوراق المالية الصادر بالقانون رقم 93 لسنة 2000 يكون تلقي الاكتتابات عن طريق أحد البنوك المرخص لها بمزاولة نشاط أمناء الحفظ.
وفي هذه الحالة يحصل المكتتب من البنك على ما يفيد سداد قيمة الاكتتاب لتقديمه لشركة الإيداع والقيد المركزي لتسليمه بيانا بقيمة مساهمته متضمنة البيانات الواردة بالمادة (2) من اللائحة التنفيذية للقانون رقم 93 لسنة 2000 المشار إليه ويقوم هذا البيان مقام صكوك الأوراق المالية، ولا يتم تداول هذه الأسهم إلا بعد قيد الإصدار في السجل التجاري وبمراعاة أحكام تخصيص الأسهم الواردة بهذه اللائحة.
وعلى الشركة إبلاغ الهيئة بالإجراءات التي تم اتخاذها في شأن الزيادة والمستندات التي تمت على أساسها بما في ذلك شهادة من البنك الذي تلقى الاكتتاب متضمنة مساهمة كل مكتتب.
*معدلة بقرار وزير الصناعة والتجارة رقم 321 لسنة 2003.$b$, E'\n', E'\r\n')),
    (28, 0, ARRAY['dbe56195fd01af46af055a34278bb4da']::text[], ARRAY['d7c016d7c453b86e2eba1670e25a2ea4']::text[], '0a39d795b52c695ab898fbca7cddb960', replace($b$إذا لم يتم تغطية الاكتتاب خلال المدة المحددة وجب على الاكتفاء بما تم تغطيته.
ويجوز لكل مكتتب -في هذه الحالة - طلب رد مبالغ الاكتتاب التي دفعها، وعلى الشركة رد هذه المبالغ كاملة بما فيها مصاريف الإصدار فور طلبها.
*معدلة بقرار وزير الصناعة والتجارة رقم 321 لسنة 2003$b$, E'\n', E'\r\n')),
    (29, 0, ARRAY['ab4997253f0c5cf356c6f2caaa592cca']::text[], ARRAY['d5593dd8f00126bec9e1adf48b81cbe7']::text[], 'ccc2881c4a5c3cc01ba2e8c77fda795e', replace($b$على الشركة والجهة التي تتلقى الاكتتاب إخطار الهيئة خلال أسبوعين من تغطية الاكتتاب في أسهم الزيادة.
وإذا تحققت الهيئة من صحة إجراءات الاكتتاب وتمامه أبلغت الشركة بموافقتها لإجراء التعديل اللازم في السجل التجاري.
وعلى الشركة التقدم بطلب التعديل للسجل التجاري خلال أسبوعين من تاريخ إبلاغها بموافقة الهيئة.
ولا يجوز سحب المبالغ الناتجة عن الاكتتاب إلا بعد تقديم شهادة من مكتب السجل التجاري بإجراء التعديل وفقا للأحكام السابقة.
وذلك مع عدم الإخلال بالأحكام المنصوص عليها بالمادة (27) من هذه اللائحة.
*معدلة بقرار وزير الصناعة والتجارة رقم 321 لسنة 2003$b$, E'\n', E'\r\n')),
    (30, 0, ARRAY['5f1f0d640efdb32492edb056999bef29']::text[], ARRAY['2d55289251153328a3243aac1b35cd8c']::text[], '2a370aa585b68c8cf6a21084a306c0cb', replace($b$تلتزم الشركات المقيدة لها أسهم في إحدى البورصات المصرية والشركات التي طرحت أسهمها في اكتتاب عام في حالة زيادة رأسمالها بإعمال حقوق الأولوية للمساهمين القدامى في الاكتتاب في أسهم زيادة رأس المال بأسهم اسمية نقدية.
ولا يجوز أن يتضمن قرار زيادة رأس المال اقتصار هذا الحق على بعض المساهمين دون البعض الآخر ومع عدم الإخلال بما يتقرر للأسهم الممتازة من حقوق.
ويتم خلال فترة الاكتتاب في زيادة رأس المال تداول حق الأولوية في الاكتتاب منفصلًا عن الأسهم الأصلية وذلك كله ما لم تقرر الجمعية العامة غير العادية للشركة التنازل عن إعمال حقوق الأولوية عند زيادة رأس المال وبمراعاة المادة (32) من هذه اللائحة.
*معدلة بقرار وزير الاستثمار رقم 95 لسنة 2016$b$, E'\n', E'\r\n')),
    (31, 0, ARRAY['6aab28233ebcdc5913c002e1d9c32d87']::text[], ARRAY['eeec2d059385482bba8b10b800570802']::text[], '76ad5431f5042132807cede10b82cec2', replace($b$لا يجوز أن تقل المدة التى يكون للمساهمين القدامى فيها حق الأولوية فى الاكتتاب فى أسهم الزيادة فى حالة تقريره عن خمسة عشر يومًا تبدأ من تاريخ فتح باب الاكتتاب فى تلك الأسهم.
ومع ذلك تنتهى المدة المُشار إليها - قبل مضى الخمسة عشر يومًا -بتمام اكتتاب المساهمين القدامى فى أسهم الزيادة كل بحسب نصيبه فيها .
*معدلة بقرار رئيس مجلس الوزراء رقم 2423 لسنة 2024.$b$, E'\n', E'\r\n')),
    (32, 0, ARRAY['0715706746d9170edb9161c8464a36e7']::text[], ARRAY['001299fb66c743c5cffa493c2258b826']::text[], 'e8f3b541058574731b75050194346d30', replace($b$يجوز بقرار من الجمعية العامة غير العادية بناء على طلب مجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال، وللأسباب الجدية التي يبديها أي منهم ويقرها مراقب الحسابات بتقرير منه، أن تطرح أسهم الزيادة كلها أو بعضها للاكتتاب العام مباشرة دون إعمال حقوق الأولوية للمساهمين القدامى إذا كانت مقررة في النظام الأساسي للشركة. كما يجوز للجمعية العامة غير العادية بناء على طلب مجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال، وللأسباب الجدية التي يبديها أي منهم ويقرها مراقب الحسابات بتقرير منه، أن تطرح أسهم الزيادة كلها أو بعضها في اكتتاب خاص لشخص أو جهة واحدة محددة أو أكثر دون إعمال حقوق الأولوية للمساهمين القدامى إذا كانت مقررة في النظام الأساسي للشركة سواء كانت الزيادة نقدا أو باستخدام الأرصدة الدائنة، على أن يُعرض على المساهمين في الجمعية العامة الأسباب والمبررات الموجبة لذلك وتقرير مراقب الحسابات عنها والمزايا التي تعود على الشركة من الاكتتاب الخاص، وأن يتم استبعاد نسبة الأسهم وحقوق التصويت المقررة للمخاطبين بالاكتتاب الخاص، وأطرافهم المرتبطة - في حالة وجودها - عند التصويت على القرار، وذلك ما لم يوافق جميع قدامى المساهمين على هذا الاكتتاب.
ويقصد بالأطراف المرتبطة وفقا لأحكام الفقرة السابقة، الأشخاص الطبيعيون وأي من أقاربهم حتى الدرجة الثانية، والأشخاص الاعتبارية والكيانات والاتحادات والروابط والتجمعات المالية المكونة من شخصين أو أكثر التي تكون غالبية أسهمهم أو حصص رأس مال أحدهما مملوكة مباشرة أو بطريق غير مباشر للطرف الآخر أو يكون مالكها شخصا واحدا، كما يعد من الأشخاص المرتبطة، الأشخاص الخاضعون للسيطرة الفعلية لشخص آخر، أو الأشخاص الذين يجمع بينهم اتفاق عند التصويت في اجتماعات الجمعية العامة للشركة أو مجلس إدارتها.
*معدلة بقرار وزير الإستثمار رقم 45 لسنة 2015$b$, E'\n', E'\r\n')),
    (33, 0, ARRAY['d75b1c2eb559d0631496f83d77196382']::text[], ARRAY['269686fdc5808b4123f86e422fa92c5c']::text[], 'cad7b7ca4febb717a17ec998c484594d', replace($b$يتم إخطار المساهمين القدامى بإصدار أسهم زيادة رأس المال بإعلان ينشر في صحيفتين يوميتين إحداهما على الأقل باللغة العربية قبل الموعد المقرر لبدء الاكتتاب بسبعة أيام على الأقل، ويجب أن يتضمن الإعلان ما يأتي:
1_ اسم الشركة وشكلها القانوني ومركزها الرئيسي وعنوانه.
2_ أن تفصح الشركة فى نشرة الاكتتاب أو مذكرة المعلومات بحسب الأحوال عن كامل البيانات التى تشتمل عليها شهادة التصنيف الائتمانى.
3_ أن تقدم الشركة للهيئة شهادة تصنيف جديدة خلال شهر من انتهاء كل سنة طوال فترة سريان السندات أو صكوك التمويل.
4_ حقوق الأولوية المقررة للمساهمين القدامى في الاكتتاب في أسهم الزيادة وكيفية ممارسة هذه الحقوق.
5_ قيمة الأسهم الجديدة.
6_ اسم الجهة التي تودع فيها مبالغ الاكتتاب وعنوانها.
7_ بيان الحصص العينية أو حصص التوصية في حالة وجودها وقيمتها والأسهم المخصصة لها.
وإذا كانت الشركة لم تطرح أسهما لها للاكتتاب العام يجوز أن يكون الإخطار بكتاب موصى عليه قبل فتح باب الاكتتاب بأسبوعين على الأقل متضمنا البيانات المشار إليها.
*تم تعديل البند 2 و3 من المادة بقرار رئيس مجلس الوزراء رقم 2423 لسنة 2024.$b$, E'\n', E'\r\n')),
    (34, 0, ARRAY['7d702eecbaed537274d843e2ff458527']::text[], ARRAY['77a3d28a86df77227134ed7a6e025b32']::text[], 'f3334182a0e17fbb837219b174c4cc17', replace($b$يجوز لشركات المساهمة وشركات التوصية بالأسهم إصدار سندات وصكوك تمويل متنوعة لمواجهة الاحتياجات التمويلية للشركة أو لتمويل نشاط أو عملية بذاتها.
ويشترط لطرح السندات أو صكوك التمويل بقيمة تجاوز صافي أصول الشركة حسبما يحدده مراقب الحسابات وفقا لآخر قوائم مالية وافقت عليها الجمعية العامة، أو لطرحها للاكتتاب العام، الشروط الآتية:
1. أن تقدم الشركة للهيئة شهادة بالتصنيف الائتماني المنصوص عليها في المادة (7) - ثالثا - بند (11) من هذه اللائحة على ألا تقل درجته عن المستوى الدال على القدرة على الوفاء بالالتزامات التي ترتبها السندات أو الصكوك، وذلك وفقا للقواعد التي يحددها مجلس إدارة الهيئة.
2. أن تفصح الشركة في نشرة الاكتتاب أو الدعوة إليه بحسب الأحوال عن كامل البيانات التي تشتمل عليها شهادة التصنيف الائتماني.
3. أن تقدم الشركة للهيئة شهادة تصنيف جديدة خلال شهر من انتهاء كل سنة مالية طوال فترة سريان السندات أو صكوك التمويل.
4. أن تنشر الشركة كامل بيانات التصنيف في صحيفتين يوميتين واسعتي الانتشار خلال خمسة عشر يوما من صدور شهادته الأصلية ومن صدور كل شهادة تكون قد اشتملت على تغيير في درجة التصنيف.
*معدلة بقرار وزير الإقتصاد رقم 586 لسنة 2000$b$, E'\n', E'\r\n')),
    (34, 1, ARRAY['3004a4e00b4167656f2cd3dd50672595']::text[], ARRAY['da5360f17248b948ad46e0d8f9838b5f']::text[], '0f13615b09d1185b5532c3e801600650', replace($b$يجوز للأشخاص الاعتبارية العامة ووحدات الإدارة المحلية، بعد موافقة وزارة المالية إصدار سندات إيراد لتمويل مشروعاتها الإنتاجية أو الخدمية، ويتم سداد قيمة هذه السندات بالإضافة إلى عوائدها باستخدام التدفقات النقدية المتولدة عن تلك المشروعات وغيرها من الإيرادات التي تحددها الجهة مصدرة السندات.
ويضع مجلس إدارة الهيئة بعد أخذ رأي وزارة المالية القواعد والإجراءات المنظمة لإصدار سندات الإيراد وسداد قيمتها بالإضافة إلى عوائدها.
وفيما عدا أحكام هذه المادة تسري على سندات الإيراد الأحكام الواردة بهذا الفرع.
*مضافة بقرار وزير الاستثمار والتعاون الدولي رقم 22 لسنة 2014$b$, E'\n', E'\r\n')),
    (35, 0, ARRAY['a1766d584251eca6db4bfe84ecbc8738']::text[], ARRAY['c258bf833ffc8547a2396c6873fa6e39']::text[], 'e5a526e7ee01a5c53600d586a282d2c2', replace($b$يكون إصدار السندات أو صكوك التمويل بقرار من الجمعية العامة غير العادية بناء على اقتراح مجلس إدارة الشركة أو الشريك أو الشركاء المديرين بحسب الأحوال، يرفق به تقرير من مراقب الحسابات ويتضمن القرار الشروط التي تصدر بها هذه الأوراق وبيان ما إذا كان يجوز تحويلها إلى أسهم وقواعد وأوضاع ذلك، مع مراعاة الأحكام الواردة في تاريخ العمل بهذه اللائحة في المواد (165)، (166)، (167) من اللائحة التنفيذية للقانون رقم 159 لسنة 1981.
ويتضمن قرار الجمعية العامة العائد الذي يغله السند أو الصك وأساس حسابه دون التقيد بالحدود المنصوص عليها في أي قانون.
ويجوز للجمعية العامة أن تضمن قرارها بإصدار السندات أو الصكوك قيمتها الإجمالية ومالها من ضمانات وتأمينات مع تفويض مجلس إدارة الشركة في تحديد الشروط الأخرى المتعلقة بها.
ويجب إصدار تلك الأوراق خلال مدة أقصاها نهاية السنة المالية التالية لقرار الجمعية العامة.$b$, E'\n', E'\r\n')),
    (35, 1, ARRAY['132d37b0435567981c38dbf94e05602e']::text[], ARRAY['663802d6b094f3eeff27ef2deeecede8']::text[], '7c3a1807e0e9d0808ae5cca65ccaec5b', replace($b$يجوز للجمعية العامة غير العادية للشركة مصدرة السندات أو صكوك التمويل أو الجهة المختصة بذلك في غير الشركات بحسب الأحوال - أن تصدر موافقتها على القيمة الإجمالية للإصدار وأن تفوض مجلس إدارتها في تنفيذه على عدة دفعات مع مراعاة الشروط الآتية:
1. موافقة الهيئة على نشرة الاكتتاب أو مذكرة المعلومات الخاصة بالإصدار الإجمالي للسندات أو الصكوك وفقا للأحكام المنصوص عليها في هذه اللائحة والقرارات الصادرة تنفيذا لها بالنسبة لنشرات الاكتتاب العام في السندات ومذكرات المعلومات.
2. أن تتضمن نشرة الاكتتاب العام أو مذكرة المعلومات للإصدار الإجمالي خطة الإصدار مبينا بها تنفيذ الإصدار على دفعات وما يطرح منه طرحا عاما أو خاصا وغير ذلك من البيانات التي تحددها الهيئة.
3. ألا تتجاوز الفترة التي تصدر خلالها الدفعات ثلاث سنوات من تاريخ موافقة الهيئة على الإصدار الإجمالي. 4. إخطار الهيئة قبل إصدار كل دفعة بأسبوعين عل الأقل وفقا لنموذج إخطار الإصدار الذي تعده الهيئة على أن يرفق به قرار مجلس الإدارة بالإصدار وشهادة بالتصنيف الائتماني في الحالات التي تحددها الهيئة، وللجهة المصدرة السير في إجراءات الإصدار إذا لم تعترض الهيئة على إخطار الإصدار خلال أسبوع من تقديمه.
5. نشر إخطار الإصدار على الموقع الالكتروني للجهة المصدرة وإخطار الهيئة وبورصة الأوراق المالية به وكذلك نشره وفقا لأحكام طرح الأوراق المالية في اكتتاب عام إذا كان الإصدار الإجمالي أو الدفعة الجديدة أو أي من أوراق الجهة المصدرة مطروحا للاكتتاب العام.
6. الالتزام بالضوابط التي تصدرها الهيئة بشأن الإفصاح عن الإصدار على دفعات.
7. سداد الرسوم المقررة للإصدار لكل دفعة على حدة.
*معدلة بقرار وزير الإستثمار رقم 64 لسنة 2010$b$, E'\n', E'\r\n')),
    (35, 2, ARRAY['3cc88f92dd1ed3a5b0b67c3b2d784c73']::text[], ARRAY['4ed0679bfde3e7afd9ed4457c55ccf7f']::text[], '1ab23b47d1bcd78dd9286d0952f83e7e', replace($b$يجوز إصدار سندات وصكوك تمويل دون الالتزام بتقديم تصنيف ائتماني لها بشرط أن يكون طرحها طرحاً خاصاً، وفقاً للقواعد التي يضعها مجلس إدارة الهيئة، على أن تتضمن هذه القواعد على وجه الأخص الآتي:
1. تحديد المؤسسات المالية والأشخاص من ذوي الملاءة المالية الذين يجوز لهما الاكتتاب فيها.
2. متطلبات الإفصاح الواجب الالتزام بها طوال فترة السندات وصكوك التمويل المشار إليها.
ولا يجوز قيد هذه السندات وصكوك التمويل في إحدى البورصات المصرية إلا بموافقة مسبقة من الهيئة في كل حالة على حدة، على أن يتم الإعلان عن ذلك، ووفقاً للضوابط التي يضعها مجلس إدارة الهيئة في هذا الشأن.
*مضافة بقرار وزير الاستثمار والتعاون الدولي رقم 6 لسنة 2016.$b$, E'\n', E'\r\n')),
    (35, 3, ARRAY['dc459705e3ca8f40d00eea4e5d3d7c43']::text[], ARRAY['3f5cf6fee01174fb77ede3e1a34a185e']::text[], 'bbc398535c5c4c7088bbf1453eb78a22', replace($b$يجوز للجمعية العامة العادية تفويض مجلس ادارة الشركة فى اصدار سندات وصكوك للتمويل والاوراق المالية الاخرى قصيرة الاجل (ادوات دين قصيرة الاجل) لمدة لا تجاوز سنتين سواء للاصدار المنفرد او برنامج الاصدارات، وفقا للقواعد والاجراءات التى يضعها مجلس ادارة الهيئة فى شأن طرحها فى اكتتاب عام او خاص ، وموافقة السلطة المختصة فى غيرها من الاشخاص الاعتبارية.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (35, 4, ARRAY['f452c1457c8b4b9a041b7d15ca7b4cea']::text[], ARRAY['45e38e2e3b03af482340ad62eedb08aa']::text[], 'bcc08210a0087960177ecf5700f29ac4', replace($b$مع عدم الاخلال بالاحكام والاجراءات المنظمة لاصدار السندات بقانون سوق رأس المال وهذه اللائحة التنفيذية يجوز اصدار سندات وصكوك تمويل خضراء تخصص حصيلتها لتمويل واعادة تمويل المشروعات الخضراء الصديقة للبيئة بمراعاة المفاهيم والقواعد والاجراءات الاتية:
1. تصدر السندات الخضراء كاحد انواع السندات وتخصص حصيلتها لتمويل واعادة تمويل المشروعات الخضراء (الصديقة للبيئة).
2. انواع السندات الخضراء:
أ. سندات خضراء تستخدم حصيلتها فى مشاريع صديقة للبيئة:
يتم استخدام حصيلة السندات فى مشاريع صديقة للبيئة ويلتزم المصدر بالوفاء بقيمة السندات والعائد المستحق عليها.
ب. السندات الخضراء المولدة للايرادات:
يتم سداد الالتزامات المترتبة على السندات والعوائد من خلال الايرادات المتولدة من المشروعات التى يتم تمويلها من حصيلة السندات الخضراء.
ج. سندات التوريق الخضراء:
سندات تصدر مقابل محفظة حقوق مالية ومستحقات آجلة لشركة او مشروع صديق للبيئة.
3. اجراءات اصدار السندات الخضراء:
▪ الحصول على موافقة الهيئة العامة للرقابة المالية.
▪ اختيار احد البنوك الاستثمار المرخص لها من الهيئة والمروجين.
▪ الحصول على تصنيف ائتمائى بمراعاة احكام المادة رقم (34) من هذه اللائحة.
▪ تسعير السندات الخضراء وتحديد العائد عليها.
4. مع مراعاة احكام المادة رقم (4) من قانون سوق رأس المال، يجوز للجهات التالية اصدار سندات خضراء: ▪ الشركات والجهات المصرية.
▪ الشركات والمؤسسات الاجنبية لتمويل مشروعات داخل مصر.
5. تصدر السندات الخضراء لتمويل المشروعات الصديقة للبيئة ومن بينها
▪ مشروعات الطاقة الجديدة والمتجددة.
▪ مشروعات التكيف مع التغيرات المناخية.
▪ مشروعات استخدام الطاقة بكفاءة.
▪ مشروعات التحكم فى التلوث ومنعه.
▪ مشروعات المبانى الخضراء.
▪ مشروعات النقل النظيفة ( وسائل النقل بالكهرباء )
6. التزامات مصدرى السندات الخضراء:
▪ التزام المصدر باجراءات واضحة تشير للمزايا والفوائد البيئية وجدواها.
▪ التزام المصدر باجراءات التقييم واختيار المشروعات الصديقة للبيئة.
▪ الافصاح للمستشثمرين عن الاهداف البيئية المستدامة واجراءات تقييم المشروعات التى تستهدف البيئة النظيفة وتوافر تقرير متابعة من مصدر خارجى باتباع الاجراءات المشار اليها.
▪ الالتزام باتخاذ اجراءات التعرف على مدى توافق المشروعات الممولة بالسندات الخضراء باشتراطات البيئة النظيفة.
▪ الالتزام باستخدام مصدر السندات الخضراء لحصيلة الاصدار من خلال اجراءات داخلية فى المشروعات الخضراء واستخدام حساب فرعى لهذا الغرض Sub-account ومحفظة مخصصة للاستثمار فى المشروعات الخضراء قيام مراقب الحسابات من المقيدين بسجل الهيئة باعداد تقرير عن استخدام التمويل للمشروعات الخضراء.
7. التقارير
▪ الالتزام بصورة دورية باعداد تقارير حول اجراءات استخدام التمويل وتخصيصها للمشروعات الخضراء وتحديد المشروعات الخضراء التى يستخدم لها التمويل، على ان يتم اصدار تقرير سنوى من مصدر السندات الخضراء للتأكيد على استخدام خطوات واجراءات تمويل المشروعات الصادر بشأنها السندات الخضراء مرفقا بها تقرير من مراقب الحسابات.
▪ اعداد الخبراء والمؤسسات الاستشارية المستقلة تقارير دراسة لتقييم واختبار المشروعات الصديقة للبيئة ( المشروعات الخضراء ) وتحديد مدى توافق المشروعات الممولة بحصيلة السندات الخضراء باشتراطات البيئة النظيفة واعداد التقارير الدورية ويتم اختيار الخبراء والمؤسسات الاستشارية اليها من بين المقيدين فى جداول بالهيئة يتم اعداده بالتنسيق مع وزارة شئون البيئة.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (35, 5, ARRAY['50257ce26b78dccbeeb4f574d51f67f4']::text[], ARRAY['4da8a528f0f969a8fd2ddb3e9a72dcdb']::text[], '45bebb91bdc010f05dcfe14092450fc4', replace($b$يجوز إصدار السندات التالية لتمويل المشروعات والأنشطة المتعلقة بمجالات التنمية المستدامة:
1. سندات التنمية المستدامة: أحد أنواع السندات المخصصة لتمويل أهداف التنمية المستدامة فقط، وتستخدم حصيلتها فى تمويل المشروعات الخضراء ومشروعات التنمية الاجتماعية التى تهدف إلى تحقيق الاستدامة من خلال الأهداف التنموية المراعية للأبعاد البيئية والاجتماعية.
2. السندات المرتبطة بالتنمية المستدامة: أحد أنواع السندات التى ترتبط هيكليًا بتحقيق المصدر لأهداف التنمية المستدامة، ولا يشترط فيها تمويل مشروعات مستدامة معينة ولكنها تمول الأداء العام للمصدر الذى لديه أهداف استدامة واضحة، ويمكن إصدارها لأى نوع من سندات الاستدامة ، ومن أمثلتها : السندات المرتبطة بمؤشر الأداء الرئيسى أو المرتبطة بأهداف التنمية المستدامة.
3. السندات ذات البعد الاجتماعى: أحد أنواع السندات التى تستخدم حصيلة طرحها لتمويل أو إعادة تمويل مشروعات اجتماعية جديدة أو قائمة.
4. سندات تمكين المرأة : أحد أنواع السندات ذات البعد الاجتماعى ، والتى ترتبط هيكليًا بتحقيق المصدر لأهداف تمويل ، المشروعات أو المبادرات أو السياسات التى تدعم قضايا تمكين المرأة فى كافة المجالات وتعزيز المساواة بين الجنسين ، ويجب أن يشغل عضوية مجلس إدارة مصدر هذه السندات نسبة لا تقل عن (25%) من النساء، أو أن تتملك امرأة واحدة أو أكثر فيه نسبة لا تقل عن (51%) من رأس ماله ، أو ألا تقل نسبة توظيف أو عمالة النساء به عن الثلث ، أو أن يشجع فى سياساته المساواة بين الجنسين فى بيئة العمل ، أو أن يقدم ويطور ثلث منتجاته أو خدماته على الأقل لتحسين نوعية الحياة للمرأة.
5. سندات المناخ: أحد أنواع السندات التى تخصص حصيلتها لتمويل وإعادة تمويل المشروعات الصديقة للبيئة بغرض تقليل الانبعاثات الكربونية والتخفيف من آثار تغير المناخ وظاهرة الاحتباس الحرارى، ويشترط لإصدار هذه السندات إعداد تقرير من مراقب بيئي معتمد للوقوف على مدى وفاء السندات المصدرة بمتطلبات معايير سندات المناخ.
6. السندات البيئية (الانتقالية): أحد أنواع السندات التى تهدف لتمويل الأنشطة الملوثة للبيئة والتى ترغب فى الانتقال بأنشطتها وتطويرها لتكون أقل تأثيرًا على البيئة، وتصدر هذه السندات عن الجهات غير المؤهلة لإصدار السندات الخضراء بسبب ممارستها لأنشطة ملوثة للبيئة ؛ كالأنشطة الصناعية، والطيران والشحن، والصناعات الكيميائية، والنفط والغاز، ومشروعات استدامة الحد من التلوث وتقليل انبعاثات الغازات المسببة للاحتباس الحرارى وتغير المناخ وتخفيف تلوث الهواء ومشروعات الحد من المخرجات الملوثة للمياه والمشروعات المستنفذة للطاقة ، وذلك بمراعاة وضع المصدر لخطة واضحة وأهداف محددة تجاه الحد من التلوث البيئي على أن يلتزم بدفع فائدة إضافية على التمويل تحدد بمقدار ما حققته من نفع بإصدارها للسندات فى حال عدم تحقيق هذه الأهداف.
*مضافة بموجب قرار رئيس مجلس الوزراء رقم 3456 لسنة 2022.$b$, E'\n', E'\r\n')),
    (35, 6, ARRAY['a2b0f1db042ae398b14eac583f7b0bdb']::text[], ARRAY['56c9edcdd8a86fdde1775f95f8656ff9']::text[], '737b148eb26f6841bc0bb97bd45b171e', replace($b$مع عدم الإخلال بالأحكام والإجراءات المنظمة لإصدار السندات الواردة بالقانون وهذه اللائحة، يجوز إصدار السندات المشار إليها بالمادة (35 مكررًا 4) من هذه اللائحة، وفق القواعد والإجراءات الآتية:
أولاً - إجراءات إصدار السندات:
1. الحصول على موافقة الهيئة.
2. اختيار أحد بنوك الاستثمار المرخص له من الهيئة والمروجين.
3. الحصول على تصنيف ائتمانى بمراعاة أحكام المادة (34) من هذه اللائحة.
4. إصدار تقرير من أحد مراقبى الحسابات المستقلين المقيدين لدى الهيئة بشأن توافق المشروعات المستهدفة مع الغرض من الإصدار، وكذا تقرير من إحدى المؤسسات الاستشارية المستقلة حال كون السندات المصدرة متعلقة بالبيئة.
5. تسعير السندات وتحديد العائد عليها.
ثانيًا - الجهات المسموح لها بإصدار السندات:
مع مراعاة أحكام المادة (4) من القانون ، يجوز للجهات التالية إصدار السندات المشار إليها بالمادة (35 مكررًا 4) من هذه اللائحة بمراعاة الفئات الواردة فى كل نوع من أنواع تلك السندات.
1. الشركات والجهات والهيئات المصرية.
2. الشركات والمؤسسات الدولية والإقليمية إذا كان إصدار السندات لتمويل مشروعات داخل مصر
ثالثًا - المشروعات المستهدفة بالتمويل من حصيلة السندات:
مع عدم الإخلال بالبند (5) من المادة (35 مكررًا 3) من هذه اللائحة، تصدر السندات المشار إليها بالمادة (35 مكررًا 4) لتمويل المشروعات والأنشطة المتعلقة بمجالات التنمية المستدامة ومن بينها:
1. قضايا تمكين المرأة فى كافة المجالات والمساواة بين الجنسين.
2. البنية التحتية الأساسية بتكاليف ميسرة (كمياه الشرب النظيفة والصرف الصحى والنقل والطاقة).
3. الوصول إلى الخدمات الأساسية (ومن بينها التعليم والتدريب المهنى والرعاية الصحية والتمويل والخدمات المالية).
4. توفير السكن بأسعار معقولة.
5. خلق فرص العمل والبرامج المصممة للحد من البطالة.
6. الأمن الغذائى والنظم الغذائية المستدامة
7. مواجهة الأوبئة والجوائح الصحية.
تحسين استدامة الموارد المائية والحياة البحرية، والحفاظ على الشواطئ الساحلية، والسياحة البحرية ، وأنشطة صيد الأسماك والكائنات البحرية ، واستخراج المواد الخام من البحار.
رابعًا - التزامات مصدرى السندات:
يلتزم المصدر باستخدام حصيلة السندات لأغراض تمويل أو إعادة تمويل المشروعات أو الأنشطة المتعلقة بأهداف التنمية المستدامة واتباع إجراءات واضحة تشير للمزايا والفوائد البيئية و/أو الاجتماعية وجدواها ، على أن يقدم تقارير دورية بذلك إلى الهيئة طوال عمر الإصدار مرفقًا بها تقرير من مراقب الحسابات.
وبالنسبة للسندات المرتبطة بالاستدامة بمختلف أنواعها ، فيجب أن تستخدم حصيلة السندات فى تمويل الأنشطة التشغيلية للمصدر والتزاماته المالية بشرط أن يكون واحدًا أو أكثر من مؤشرات الأداء الرئيسية له معبرًا بوضوح عن اتباعه لإجراءات وسياسات من شأنها تحقيق أهداف التنمية المستدامة ، ويجب أن يقدم المصدر تقارير دورية بذلك إلى الهيئة طوال عمر الإصدار مرفقًا بها تقرير من مراقب الحسابات ، على أن يتم الإفصاح لحملة السندات عن تلك المؤشرات فى التقارير السنوية.
خامسًا - إجراءات تقييم واختيار المشروعات:
يقوم المصدر بالآتى:
1. إجراءات تقييم واختيار مشروعات الاستدامة، وإعداد تقرير من إحدى المؤسسات الاستشارية المستقلة المعتمدة لدى الهيئة بحسب كل نوع من أنواع السندات.
2. تقديم وصف موجز للمشروعات المستهدفة بما فى ذلك النسبة المئوية للحصيلة التى تم تخصيصها لتمويل أو إعادة تمويل كل مشروع مستهدف، مرفقًا به تقرير من الخبراء أو المؤسسات الاستشارية المستقلة لاعتماد جدوى هذه الاستثمارات ومدى استهدافها لتحقيق أهداف التنمية المستدامة.
3. الإفصاح دوريًا لحملة السندات عن الأهداف البيئية و/أو الاجتماعية المستدامة والإجراءات المتبعة فى تقييم واختيار المشروعات التى تستهدف التنمية المستدامة وكيفية إدارة المخاطر البيئية والاجتماعية المادية المحتملة والمرتبطة بالمشروعات المستهدفة، على أن يقدم تأييدًا لذلك تقرير متابعة من مؤسسة استشارية مستقلة للتحقق من اتباع الإجراءات المشار إليها.
4. تقديم تقرير إفصاح سنوى بالنسبة للسندات المرتبطة بالاستدامة بمختلف أنواعها يوضح بشكل دقيق وواضح المعلومات الرئيسية بشأن الحوكمة البيئية والاجتماعية والمؤسسية التى تنطبق عليها ، على أن يتم الإفصاح به عن استراتيجية المصدر الشاملة للاستدامة ومدى مواءمتها مع استراتيجيته ، والإطار الزمنى لتنفيذها ، وفى حالة عدم التزام المصدر بتحقيق تلك الأهداف فى الإطار الزمنى المحدد لها وفقًا للتقرير الذى يعده مراقب الحسابات فى هذا الشأن فيلتزم المصدر بتعويض حملة السندات بزيادة قيمة الفائدة المستحقة عن السندات المصدرة وفقًا لما هو مبين بنشرة الاكتتاب أو مذكرة المعلومات بحسب الأحوال.
سادسًا - إدارة حصيلة السندات:
يلتزم المصدر بفتح حساب فرعى لغرض إدارة حصيلة إصدار السندات ومحفظة مخصصة للاستثمار فى المشروعات المستهدفة.
سابعًا - التقارير:
يتولى مصدر السندات إعداد التقارير الآتية:
1. تقارير سنوية طوال عمر السندات وحتى تمام استحقاقها للتأكد والتحقق من تنفيذ خطوات وإجراءات تمويل المشروعات المستهدفة من حصيلة السندات، مرفقًا بها تقرير من مراقب الحسابات. 2. تقارير سنوية بشأن إجراءات استخدام حصيلة الإصدار وتخصيصها لمشروعات التنمية المستدامة بأنواعها طوال عمر السندات، والالتزام بالإفصاح عن أى تعديلات تطرأ على المشروعات الممولة السابق الإفصاح عنها، على أن تتضمن تلك التقارير الإفصاح عن المشروعات التى تم تمويلها، فضلًا عن وصف موجز للمشروعات والمبالغ المخصصة لها وأثرها المتوقع.
3. تقرير الإفصاح عن استراتيجية الاستدامة الشاملة المتبعة من قبل المصدر.
4. تقارير سنوية معدة من الخبراء والمؤسسات الاستشارية المستقلة لتقييم وتحديد مدى توافق المشروعات الممولة مع معايير ومبادئ الاستدامة الدولية ، على أن يتم اختيار الخبراء والمؤسسات الاستشارية المستقلة من بين المقيدين بالجداول المعدة لذلك لدى الهيئة ، وفيما يخص المشروعات المتعلقة بقضايا التغير المناخى وظاهرة الاحتباس الحرارى فيلتزم المصدر بتقديم تقرير سنوى من مراقب بيئى خارجى معتمد للوقوف على مدى وفاء السندات المصدرة بمتطلبات معايير سندات المناخ/ السندات البيئية. وبالنسبة للسندات ذات البعد الاجتماعى وسندات تمكين المرأة والسندات المرتبطة بالتنمية المستدامة ، فيتم الاستعانة بمراقب حسابات المصدر للتحقق من مدى توافق تلك السندات مع الشروط والأحكام والضوابط المحددة المنظمة لتلك الأنواع من السندات ، وإعداد تقارير بذلك عند الإصدار وطوال عمر السند
ثامنًا - التزامات الخبراء والمؤسسات الاستشارية المستقلة:
يتولى الخبراء والمؤسسات الاستشارية المستقلة إعداد تقارير دورية لتقييم واختبار المشروعات المستهدفة لتحقيق أهداف الاستدامة البيئية، وتحديد مدى توافق المشروعات الممولة بحصيلة السندات مع المعايير والمبادئ الدولية الخاصة بها بحسب كل نوع من هذه السندات ، ويتم اختيار الخبراء والمؤسسات الاستشارية من بين المقيدين بسجل مراقبى البيئة المستقلين-مراقبى الاستدامة.
تاسعًا - التزامات مراقب الحسابات:
يتولى مراقب الحسابات إعداد تقارير سنوية - بمراعاة معايير المراجعة المصرية - بشأن مدى التزام مصدر السندات المشار إليها بالمادة (35 مكررًا 4) من هذه اللائحة - باستخدام حصيلة السندات فى الأغراض والأنشطة الواردة فى نشرة الاكتتاب أو مذكرة المعلومات بحسب الأحوال ، وعلى الأخص الآتى:
1. مدى تنفيذ خطوات وإجراءات تمويل المشروعات المستهدفة من حصيلة السندات، وذلك طوال عمر الإصدار وحتى تمام الاستحقاق.
2. مدى التزام المصدر بما ورد بتقرير الإفصاح المعد منه بشأن المعلومات الرئيسية للحوكمة البيئية والاجتماعية والمؤسسية المنطبقة على السندات، ومدى مواءمتها مع استراتيجية المصدر والإطار الزمنى لتنفيذها.
3. مؤشرات الأداء الرئيسية له، والتحقق من مدى توافقها مع استراتيجية المصدر العامة فيما يخص الاستدامة، وذلك فى حالة السندات المرتبطة بالتنمية المستدامة بكافة أنواعها.
*مضافة بموجب قرار رئيس مجلس الوزراء رقم 3456 لسنة 2022.$b$, E'\n', E'\r\n')),
    (35, 7, ARRAY['d6df109fb70cbae1842503e5a2a0a2e3']::text[], ARRAY['c13e8da974e27e1a4e45c27ad243476b']::text[], '21d1322a18cc25c0f9900d8393bb4202', replace($b$يجوز إصدار سندات توريق فى المجالات المرتبطة بالسندات المشار إليها بالمادة (35 مكررًا 4) من هذه اللائحة بشرط اتفاق سياسات الجهة المحيلة مع مبادئ التنمية المستدامة، أو أن تتوافر فيها أحد المعايير المتعلقة بأهداف التنمية المستدامة، أو أن تكون الحقوق المالية المحالة مرتبطة بمشروعات تستهدف تحقيق أهداف التنمية المستدامة، كما يجوز إصدار صكوك فى المجالات المشار إليها لتمويل الجهات المستفيدة لمشروعات تستهدف تحقيق أهداف التنمية المستدامة.
ويسرى فى شأن إصدار سندات التوريق والصكوك المشار إليهما بالفقرة السابقة، القواعد والإجراءات المنصوص عليها فى المادة (35 مكررًا 5) من هذه اللائحة.
*مضافة بموجب قرار رئيس مجلس الوزراء رقم 3456 لسنة 2022.$b$, E'\n', E'\r\n')),
    (35, 8, ARRAY['98a54aa8637a03b5e17a96a0c96c57b7']::text[], ARRAY['61f5bce1fe0ad8343848e2c13b320232']::text[], '1e2d91eb3054fbd33af75cc005583956', replace($b$تنشأ بالبورصة المصرية سوق طوعية لتداول "شهادات خفض الانبعاثات الكربونية". وتُعد تلك الشهادات أدوات مالية قابلة للتداول، ويُقصد بها "وحدات خفض انبعاثات غازات الاحتباس الحراري، وتصدر لصالح أية جهة تنفذ مشروعات خفض انبعاثات غازات الاحتباس الحراري بعد الحصول على موافقة الجهات المعنية ذات الاختصاص، وتمثل كل "وحدة" طنًا من ثانى أكسيد الكربون المكافئ تم تخفيضه.
وتلتزم كافة الجهات الحكومية وقطاع الأعمال العام والقطاع الخاص وكافة مطوري المشروعات بإخطار الهيئة ووزارة البيئة بجميع المشروعات التى سوف يصدر لها شهادات خفض الانبعاثات الكربونية.
وتلتزم الجهات المصدر لها شهادات خفض انبعاثات كربونية بالإفصاح عن أى أحداث أو تغيرات تطرأ بشأن الموافقات الصادرة لها من الجهات المعنية ذات الاختصاص طوال مدة الإصدار.
*مضافة بموجب قرار رئيس مجلس الوزراء رقم 4664 لسنة 2022.$b$, E'\n', E'\r\n')),
    (35, 9, ARRAY['29795131dbb8fbfa0aaf3f26d220426a']::text[], ARRAY['b22a26c159222fde9748c674b15d2584']::text[], 'ba7197b58c8ae6664b58a7d9e03ff650', replace($b$تُشكل بقرار من مجلس إدارة الهيئة بالتنسيق مع وزارة البيئة لجنة تضم فى عضويتها ممثلين عن الجهات المعنية، تسمى "لجنة الإشراف والرقابة على وحدات خفض الانبعاثات الكربونية" تتولى وضع القواعد الخاصة بإصدار شهادات خفض الانبعاثات الكربونية وإتاحتها للتداول، والإشراف والرقابة عليها ويحدد القرار الصادر بتشكيل اللجنة اختصاصاتها ونظام عملها.
وتُعد الهيئة قاعدة بيانات لتسجيل المشروعات التى صدر لها شهادات خفض الانبعاثات الكربونية، وتقوم بموافاة وزارة البيئة بتلك المشروعات بصورة شهرية.
وتُصدر البورصة المصرية قواعد وإجراءات التداول على تلك الشهادات، على ألا تكون سارية إلا بعد اعتمادها من الهيئة.
*مضافة بموجب قرار رئيس مجلس الوزراء رقم 4664 لسنة 2022.$b$, E'\n', E'\r\n')),
    (36, 0, ARRAY['29d7aec38531459e4ffcd4ed25b98d4f']::text[], ARRAY['fedc9cf0d9648e700d8c43a1594010fe']::text[], 'c77eae6ded18cd168c565e22cca4976a', replace($b$إذا لم يتم تغطية جميع السندات وصكوك التمويل المطروحة للاكتتاب خلال المدة المقررة يجوز لمجلس إدارة الشركة أو الشريك أو الشركاء المديرين بحسب الأحوال، أن يقرر الاكتفاء بما تم تغطيته مع إخطار الهيئة بذلك خلال أسبوع من قرار المجلس.$b$, E'\n', E'\r\n')),
    (37, 0, ARRAY['d627aca92c793a2962f3251e51222554']::text[], ARRAY['0f18fec39f24c7f7d36173d74108320b']::text[], 'a317f6af1577abc0e2a8fe71c1542fa9', replace($b$تصدر السندات أو صكوك التمويل في شكل شهادات اسمية قابلة للتداول، وتخول الصكوك أو السندات من ذات الإصدار حقوقا متساوية لحامليها في مواجهة الشركة.
ويوقع على السندات والصكوك عضوان من أعضاء مجلس إدارة الشركة يعينهما المجلس أو من الشريك أو الشركاء المديرين بحسب الأحوال.
ويكون لها كوبونات ذات أرقام مسلسلة مشتملة على رقم السند أو الصك.
النص الاصلى للمادة: تصدر السندات أو صكوك التمويل في شكل شهادات اسمية أو لحاملها قابلة للتداول، وتخول الصكوك أو السندات من ذات الإصدار حقوقا متساوية لحامليها في مواجهة الشركة.
ويوقع على السندات والصكوك عضوان من أعضاء مجلس إدارة الشركة يعينهما المجلس أو من الشريك أو الشركاء المديرين بحسب الأحوال.
ويكون لها كوبونات ذات أرقام مسلسلة مشتملة على رقم السند أو الصك.
*تم إلغاء الاحكام المنظمة للأسهم لحامله الواردة بالمادتين ( 1 الفقرة الثانية ) ، (37) وفقا لقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (38, 0, ARRAY['1fbd59d7a38a7b4105d2a269b4e23267']::text[], ARRAY['73cbe07c8b651b2646fd149af1d8731b']::text[], '1fbd59d7a38a7b4105d2a269b4e23267', replace($b$ملغاة
*ملغاة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018.$b$, E'\n', E'\r\n')),
    (39, 0, ARRAY['91ce44820f95d86cb6ec49acb28d02c7']::text[], ARRAY['83d85a155702c97d804f5653645e1815']::text[], '6eb67a7bfe500498ef23ec6b4683e7d9', replace($b$تسري على السندات وصكوك التمويل القواعد والأحكام المقررة للأسهم الواردة بالقانون وهذه اللائحة وذلك فيما لم يرد بشأنه نص خاص فيها.
*معدلة بقرار وزير الإقتصاد رقم 44 لسنة 2000.$b$, E'\n', E'\r\n')),
    (40, 0, ARRAY['0a331b1be7ffd7daee329eb53a155672']::text[], ARRAY['659af51bd5a8a06dc6371e1b28dffe26']::text[], '42b03dedbf359c109624d5a50d8f6387', replace($b$لا تكون الأسهم مطروحة للاكتتاب العام في السوق الأولى أو الطرح العام في سوق التداول إلا في حالة دعوة أشخاص غير محددين سلفا إلى الاكتتاب في تلك الأسهم، ولا يشترط حد أدنى لعدد أو قيمة الأسهم التي يتم طرحها في اكتتاب عام أو طرح عام.
ولا يجوز الدعوة للاكتتاب العام - بما في ذلك شركات قطاع الأعمال العام وشركات القطاع العام - إلا بناء على نشرة معتمدة من الهيئة وعلى النماذج التي تعدها أو تقرها على أن يبين فيها بطريقة واضحة أن اعتماد الهيئة للنشرة ليس اعتمادا للجدوى التجارية للنشاط موضوع النشرة أو لقدرة المشروع على تحقيق نتائج معينة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (41, 0, ARRAY['dcfe16d505dc35119bcb78f931e6b4bc']::text[], ARRAY['324d784dbf2565e29fb57320b792c484']::text[], 'a2c8ac647a59a250c28840b9f55d40c0', replace($b$يجب ألا يقل رأس المال المصدر عند التأسيس لكل من شركة المساهمة وشركة التوصية بالأسهم التي تطرح أسهما لها للاكتتاب العام عن مليون جنيه على ألا يقل ما يكتتب فيه المؤسسون عن نصف رأس المال المصدر.
ولا يجوز أن يزيد رأس المال المرخص به للشركات التي تطرح أسهما لها في اكتتاب عام على خمسة أمثال رأس المال المصدر.$b$, E'\n', E'\r\n')),
    (42, 0, ARRAY['c3c4158efd9fe4ecae76f49420f4a0b0']::text[], ARRAY['5ca9dcda01d83ce9e3c34664ffec47f3']::text[], '56368809c35b4cb38d7f11a92ff871fa', replace($b$يجب أن تتضمن نشرة الاكتتاب في أسهم الشركة عند التأسيس بالإضافة إلى البيانات المنصوص عليها في القانون، البيانات الآتية:
1. اسم الشركة وشكلها القانوني وغرضها.
2. تاريخ العقد الابتدائي.
3. القيمة الاسمية للسهم وعدد الأسهم وأنواعها وخصائص كل منها والحقوق المتعلقة بها سواء بالنسبة إلى توزيع الأرباح أو عند التصفية.
4. المدة التي يتعين على المؤسسين التقدم فيها بطلب الترخيص بتأسيس الشركة.
5. بيان ما إذا كانت هناك حصة تأسيس، وما قدم للشركة في مقابلها، ونصيبها المقرر في الأرباح.
6. إذا كان الاكتتاب العام عن جزء من رأس المال يبين كيفية الاكتتاب في باقي رأس المال.
7. تاريخ بدء الاكتتاب والجهة التي سيتم الاكتتاب بواسطتها، والتاريخ المحدد لقفل الاكتتاب.
8. تاريخ ورقم اعتماد الهيئة للنشرة.
9. المبلغ المطلوب دفعه عند الاكتتاب بحيث لا يقل عن ربع القيمة الاسمية بالإضافة إلى مصاريف الإصدار. 10. أسماء مراقبي حسابات الشركة وعناوينهم.
11. بيان تقريبي مفصل بعناصر مصروفات التأسيس التي ينتظر أن تتحملها الشركة من بدء التفكير في تأسيسها إلى تاريخ صدور القرار بالتأسيس.
12. بيان العقود ومضمونها التي يكون المؤسسون قد أبرموها خلال الخمس سنوات السابقة على الاكتتاب ويزمعون تحويلها إلى الشركة بعد تأسيسها، وإذا كان موضوع العقد شراء منشأة قائمة نقدا فيتعين تضمين النشرة موجزا لتقرير مراقب الحسابات عن هذه المنشأة.
13. تاريخ بداية السنة المالية وانتهائها.
14. بيان عن طريق توزيع الربح الصافي للشركة.
15. طريقة تخصيص الأسهم إذا بلغت طلبات الاكتتاب أكثر من المطروح للاكتتاب.
16. المدة والحالات التي يجب فيها على الجهة التي تلقت الاكتتاب رد المبالغ إلى المكتتبين.$b$, E'\n', E'\r\n')),
    (43, 0, ARRAY['2222adc0c49c5699021e1ded58703459']::text[], ARRAY['6c136766c708e3978705d8b912cf8cd9']::text[], 'b49187e00978a2bc5dcc77d0e1c174c9', replace($b$يجب أن تتضمن نشرات الاكتتاب في زيادة رأس المال، بالإضافة إلى البيانات المنصوص عليها في القانون، البيانات الآتية:
1. رقم وتاريخ السجل التجاري للشركة.
2. تاريخ قرار الجمعية العامة أو مجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال بالزيادة والسند القانوني لهذا القرار، وبيان ما إذا كانت قيمة الأسهم من الإصدارات السابقة قد سددت بالكامل، أو أنه رخص للشركة في إصدار أسهم جديدة قبل تمام سداد قيمة تلك الأسهم.
3. مقدار الزيادة، وعدد الأسهم وقيمتها بمراعاة حكم المادة (17) من هذه اللائحة، وإذا كانت الأسهم من أنواع مختلفة فيذكر بيان واف عن خصائص كل نوع، والحقوق المتعلقة بها، سواء بالنسبة إلى توزيع الأرباح أو عند التصفية.
4. إذا كان جزء من الزيادة في مقابل أسهم عينية فتتضمن نشرة الاكتتاب البيانات الواردة في المادة (45) من هذه اللائحة.
5. بيان مفصل بالأسباب التي دعت إلى زيادة رأس المال ومدى توقع إفادة الشركة من هذه الزيادة.
6. مدى أعمال حقوق الأولوية للمساهمين القدامى في الاكتتاب.
7. بيان الرهونات والحقوق العينية الأخرى لجميع الأصول.
8. إذا كان الاكتتاب العام عن جزء من أسهم الزيادة يبين كيفية الاكتتاب في الباقي.
9. المدة والحالات التي يجب فيها على الجهة التي تلقت الاكتتاب رد المبالغ إلى المكتتبين.$b$, E'\n', E'\r\n')),
    (44, 0, ARRAY['3870c0389be10f7156f6711b1fd264c7']::text[], ARRAY['babf77d5467b651ee6af9ced8406b473']::text[], '827b5c79e42882060d7dd86e8546939b', replace($b$تتضمن نشرات الاكتتاب في الأوراق المالية الأخرى بالإضافة إلى البيانات المنصوص عليها في القانون وتلك الواردة في البندين رقمي 1، 7 من المادة السابقة، البيانات الآتية:
(أ) تاريخ قرار الجمعية العامة للشركة بالموافقة على إصدار الورقة المالية والسند القانوني لهذا القرار.
(ب) نوع الورقة المالية والعائد الذي تغله وأساس حسابه.
(ج) رقم وتاريخ ترخيص الهيئة بطرح الورقة المالية للاكتتاب العام.
(د) شروط إصدار الورقة المالية وشروط ومواعيد استردادها.
(هـ) بيان بالضمانات والتأمينات المقدمة من الشركة لأصحاب الأوراق المالية.
(و) قيمة صافي أصول الشركة محددة بتقرير من مراقب الحسابات وفقا لآخر ميزانية وافقت عليها الجمعية العامة، وإقرار من مجلس إدارة الشركة بأن السندات أو صكوك التمويل المصدرة لا تجاوز هذه القيمة وذلك ما لم تكن الشركة مرخصا لها بالإصدار بقيمة تجاوز صافي أصولها.
(ز) ملخص لمصادر التدفقات النقدية ونسب السيولة والربحية والهيكل المالي للشركة المصدرة وتقرير مراقب الحسابات عن التوقعات المستقبلية وفقا لمعايير المراجعة المصرية.
في حالة تقديم نشرة الاكتتاب من شخص اعتباري لا يتخذ شكل شركة يجب أن تتضمن نشرة الاكتتاب البيانات المنصوص عليها في القانون وفي البنود (ب)، (ج)، (د) من الفقرة الأولى من هذه المادة،، بالإضافة إلى ما يلي:
(أ) شهادة من مدير الإصدار بأنه قد حصل على كافة البيانات والمعلومات التي رآها ضرورية، وأنه بذل عناية الرجل الحريص للتأكد من كفاية وصحة المعلومات والقوائم المقدمة إلى الهيئة.
(ب) بيان من شركة القيد والإيداع المركزي بموقف سداد الجهة للإصدارات السابقة في حالة وجودها.
(ج) استمارة المعلومات وفقا للنموذج المعد من قبل الهيئة.
(د) توكيل أو تفويض صادر من المسئول التنفيذي للجهة، محدد به أسماء المفوضين بتقديم واستلام المستندات إلى ومن الهيئة.
(هـ) أية مستندات أخرى تراها الهيئة ضرورية تتفق مع الطبيعة القانونية للمصدر.
*معدلة بقرار وزير الإستثمار رقم 1 لسنة 2010$b$, E'\n', E'\r\n')),
    (45, 0, ARRAY['15b95dadb2d7dab1d92233f805b64b1a']::text[], ARRAY['6ce49eb61d35ae08b4fb98be9b6a5105']::text[], '76590b91e828e62d6c1d82f25cfd40fe', replace($b$في حالة إصدار أسهم مقابل حصة عينية سواء عند التأسيس أو عند زيادة رأس المال فيجب أن تتضمن نشرة الاكتتاب ما يأتي:
1. ملخص عن بيان الموجودات المالية والعينية المقدمة في مقابل الحصة العينية وأسماء مقدميها وشروط تقديمها، مع بيان ما إذا كانوا من المؤسسين أو أعضاء مجلس الإدارة أو الشريك أو الشركاء المديرين، ومدى إفادة الشركة من هذه الموجودات والقيمة المطلوبة لكل نوع منها أصلا.
2. بيان عن عقود المعاوضة التي وردت على العقارات المقدمة للشركة خلال السنوات الخمس السابقة على تقديمها وملخص بأهم الشروط التي تمت على أساسها هذه العقود، وما كانت تغله تلك العقارات من ريع في هذه المدة.
3. جميع حقوق الرهن والامتياز المترتبة على الحصص العينية.
4. ملخص واف عن قرار اللجنة المختصة بتقدير الحصة العينية وتاريخ صدوره.
5. عدد الأسهم المصدرة في مقابل الحصة العينية.$b$, E'\n', E'\r\n')),
    (46, 0, ARRAY['8c1a59c82dab73538f8e541a4bb9235f']::text[], ARRAY['a74904c0f4b32b861ba731f1cd4246fc']::text[], 'e867fa061d68fbe1c03deb695dde323c', replace($b$يقدم المؤسسون - قبل البدء في عملية الاكتتاب - إلى الهيئة نشرة الاكتتاب موقعا عليها من جميع المؤسسين أو من ينوب عنهم قانونا.
ويرفق بالنشرة تقرير من مراقب حسابات بصحة البيانات الواردة فيها ومطابقتها لمتطلبات القانون واللائحة، وكذلك عقد الشركة الابتدائي ونظامها الأساسي موقعا عليه من المؤسسين.
ويكون إيداع أصل نشرة الاكتتاب ومرفقاتها بالهيئة نظير إيصال مبين فيه تاريخ الإيداع.$b$, E'\n', E'\r\n')),
    (47, 0, ARRAY['cfbbeae18777642481e275485a1d46d9']::text[], ARRAY['738e4f7ca1d602276dda8f8934e75b37']::text[], '09a267f0c2c1ccc8702a6a0568a7024d', replace($b$للهيئة أن تعترض - خلال أسبوعين من تاريخ تقديم نشرة الاكتتاب إليها - على عدم كفاية أو دقة البيانات الواردة بها، وللهيئة أن تكلف المؤسسين باستكمال البيانات المشار إليها أو بتصحيحها أو تقديم أية بيانات أو توضيحات تكميلية أو أوراق أو مستندات إضافيه.
ويتم توجيه الاعتراض أو طلب استكمال البيانات وغير ذلك من الأوراق إلى المؤسسين أو من ينوب عنهم قانونا، كما تخطر الجهة التي يجري عن طريقها الاكتتاب إذا تطلب الأمر ذلك.$b$, E'\n', E'\r\n')),
    (48, 0, ARRAY['82ef981a6a2175adfdd918e0661ef5e3']::text[], ARRAY['7bca15ef3dd79137cf025ec28519e28a']::text[], '2c291978cb53d24f1c697c47036346c5', replace($b$يظل الاكتتاب مفتوحا للمدة المحددة بالنشرة بحيث لا تقل عن عشرة أيام ولا تجاوز شهرين.
وإذا لم يكتتب في جميع الأسهم المطروحة خلال تلك المدة جاز بإذن من رئيس الهيئة مد فترة الاكتتاب مدة لا تزيد على شهرين آخرين.$b$, E'\n', E'\r\n')),
    (49, 0, ARRAY['501608c5834a0b84230921c68381e4c7']::text[], ARRAY['af0a32925bd3c5edc44a370e0ee4f62d']::text[], 'dc181637999813186a774ba5fe02f213', replace($b$إذا طرأ بعد اعتماد الهيئة لنشرة الاكتتاب ما يؤثر على سلامة عملية الاكتتاب أو صحة بيانات النشرة أو تغيرت الظروف أو العناصر المادية أو القانونية التي اعتمدت بناء عليها النشرة كان لرئيس الهيئة إيقاف إجراءات الاكتتاب إلى أن يتم اتخاذ الإجراء المناسب على الوجه الصحيح خلال المدة التي يحددها، وإلا وجب على الجهة التي تلقت الاكتتاب رد المبالغ المكتتب فيها إلى المكتتبين.
ويجب إيقاف إجراءات الاكتتاب ورد المبالغ المكتتب فيها إذا كان الاكتتاب تم بالمخالفة لأحكام القانون والقرارات الصادرة تنفيذا له أو ثبت أن اعتماد النشرة تم على أساس بيانات غير صحيحة.$b$, E'\n', E'\r\n')),
    (50, 0, ARRAY['0b854f194a8d292fd977c0834d90e651']::text[], ARRAY['b1cf97ab48a54ebb8575d631907b0da3']::text[], '0be5459f63ffc87b4b5cbc22aae8817a', replace($b$ينشر موجز لنشرة الاكتتاب وتعديلاتها بعد اعتمادها من الهيئة متضمنا البيانات الرئيسية لها، وذلك على النموذج الذى تضعه الهيئة فى هذا الشأن، وفقا لوسائل النشر التى يحددها مجلس إدارة الهيئة.
على أن تتضمن تلك البيانات أماكن الحصول على نشرة الاكتتاب المعتمدة، ويجوز الحصول على نسخة معتمدة من النشرة من الهيئة بعد أداء الرسم المقرر.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (51, 0, ARRAY['ea31d6ae11a8aa3b1925695724837fbc']::text[], ARRAY['e9464f40fb716348f59ab9ae097f2cf1']::text[], '08309146b7418b498dc7e34e2973bdcd', replace($b$لا يجوز قبل اعتماد نشرة الاكتتاب من الهيئة إجراء نشر من أي نوع من بيانات النشرة يتضمن على أي وجه الترويج لأوراق مالية. ومع ذلك يجوز بعد تقديم النشرة إلى الهيئة توزيع إعلانات أو نشرات أو خطابات أو غير ذلك من البيانات الأساسية الخاصة بنشاط المشروع المقدمة عنه النشرة، على أن يشار في جميع الأحوال وبطريقة ظاهرة إلى أن نشرة الاكتتاب لم تعتمد بعد من الهيئة.$b$, E'\n', E'\r\n')),
    (52, 0, ARRAY['176b0c28ee9a3434edd5434cac982a28']::text[], ARRAY['7d56dfc9a20c0170e7ec7223ed757606']::text[], '3aa2df7240db2506b9f4fe9be0738048', replace($b$مع عدم الإخلال بما ورد بالمادة 121 من هذه اللائحة لا يجوز الاكتتاب في أسهم مضى على تاريخ اعتماد الهيئة لنشرة الاكتتاب الخاصة بها مدة أربعة شهور.$b$, E'\n', E'\r\n')),
    (53, 0, ARRAY['071659ff32e0ade9247db183cd5c7e4a']::text[], ARRAY['37c85d349210c41c364c96c026cafeff']::text[], 'f931220abc0c049eb081439f3adca7e2', replace($b$يتم الاكتتاب بموجب شهادات اكتتاب مبينا بها تاريخ الاكتتاب وموقعا عليها من المكتتب في الأسهم الاسمية، على أن يكتب بالأحرف عدد الأسهم التي اكتتب فيها. ويعطى المكتتب صورة من الشهادة متضمنة البيانات الآتية:
(أ) اسم وغرض الشركة التي يكتتب في أسهمها.
(ب) رأس مال الشركة والجزء المطروح للاكتتاب العام منه.
(ج) القيمة الاسمية للسهم وما دفع منها عند الاكتتاب.
(د) تاريخ اعتماد الهيئة لنشرة الاكتتاب.
(هـ) الحصص العينية في حالة وجودها.
(و) نوع الأسهم التي تم الاكتتاب فيها وعددها وأرقامها.
(ز) اسم الجهة التي تم فيها أداء المبالغ المطلوبة للاكتتاب.
(ح) اسم المكتتب وعنوانه وجنسيته وذلك بالنسبة إلى الأسهم الاسمية.
وتتضمن شهادة الاكتتاب في الأوراق المالية الأخرى بالإضافة إلى البيانات الواردة بالبنود (د)، (ز)، (ح) البيانات الآتية:
1. نوع الورقة المالية المطروحة للاكتتاب.
2. رقم وتاريخ ترخيص الهيئة بطرح الورقة للاكتتاب.$b$, E'\n', E'\r\n')),
    (54, 0, ARRAY['911904ba4056ca1bd89a9e8321adb8b9']::text[], ARRAY['e8234605ed096856ad5533ae3772a634']::text[], 'eda9b11c2d5e597fb4567fd5ab657a6d', replace($b$يجوز قفل باب الاكتتاب بعد تغطية قيمة الأسهم المطروحة وفقا للشروط المحددة في نشرة الاكتتاب ومضي الحد الأدنى للمدة التي يظل الاكتتاب مفتوحا فيها والمنصوص عليها في المادة 48 من هذه اللائحة.
واذا جاوز الاكتتاب عدد الاسهم المطروحة ولم يحدد نظام الشركة كيفية التوزيع بين المكتتبين، وجب تخصيصها بتوزيع عدد الاسهم الاسمية لكل من مكتتب على اساس نسبة عدد الاسهم المطروحة الى عدد الاسهم المكتتب فيها، بحيث لا يترتب على ذلك اقصاء المكتتب فى الشركة أيا كان عدد الاسهم التى اكتتب فيها، ويراعى جبر الكسور لصالح صغار المكتتبين.
ويرد إلى المكتتب ما دفعه عند الاكتتاب بالزيادة عما خصص له بالفعل.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (55, 0, ARRAY['9d1f42fe003b80291f753e5f31df5673']::text[], ARRAY['ca7eb7bac63d6dc01de9908b74ce2f7a']::text[], '6d13f76cc7b4e60afc33a22ac7f50877', replace($b$لا يجوز المضي في تأسيس الشركة إذا انتهت المدة المقررة للاكتتاب والمدة التي قد يمتد إليها ولم يغط الاكتتاب الأسهم المطروحة.
وعلى الجهة التي تلقت الاكتتاب إبلاغ الهيئة والمكتتبين بذلك خلال أسبوع من انقضاء تلك المدة وأن ترد إليهم فور طلبهم ما دفعوه بما في ذلك مصاريف الإصدار.$b$, E'\n', E'\r\n')),
    (56, 0, ARRAY['881ff19a5359ef794c385434cca73808']::text[], ARRAY['c57e194b62355478338f38282128df87']::text[], '3e13f07c9da8f850330c5ab9fc8984a3', replace($b$يجب على كل من المؤسسين والجهة التى تقلت مبالغ من المكتتبين اخطار الهيئة خلال خمسة ايام عمل التالية لقفل باب الاكتتاب، باسماء المكتتبين فى الاسهم الاسمية وجنسياتهم ومحال اقامتهم وقيمة ما دفعه كل منهم وعدد الاسهم التى اكتتب فيها ومقدار الاسهم التى خصصت له.
ويجوز لكل ذي شأن الحصول على نسخة من هذا البيان من الهيئة بعد أداء الرسم المقرر.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (57, 0, ARRAY['14a63f650ec1ce9f16eab3bdd39c8a2a']::text[], ARRAY['999303558cc9373fb3e72e3587888875']::text[], '3a17462a32ec52194c011355ee759dd4', replace($b$تظل المبالغ التي دفعت من المكتتبين تحت يد الجهة التي تلقت الاكتتاب، ولا يجوز السحب منها إلا بعد أن يقدم من ينوب عن الشركة قانونا ما يفيد إشهار نظام الشركة في السجل التجاري.
واستثناء من ذلك، وبمراعاة ما قد يرد بنشرة الاكتتاب، يتعين على الجهة التي تلقت المبالغ أن ترد إلى المكتتبين جميع ما دفعوه من مبالغ وذلك في الحالات الآتية:
(أ) إذا صدر حكم من قاضي الأمور المستعجلة بتعيين من يسحب هذه المبالغ وتوزيعها على المكتتبين، وذلك إذا لم يتم تأسيس الشركة بسبب خطأ مؤسسيها خلال ستة أشهر من تاريخ تقديم طلب التأسيس.
(ب) إذا مضت مدة سنة على تاريخ قفل الاكتتاب، دون أن يتقدم المؤسسون أو من ينوب عنهم بطلب تأسيس الشركة. (ج) إذا اتفق جميع المؤسسين على العدول عن تأسيس الشركة وقدموا إلى الجهة التي تلقت الاكتتاب إقرارا منهم بذلك مصدقا على التوقيعات الواردة فيه.
ويجوز لأصحاب الشأن فضلا عن استرداد قيمة الاكتتابات الرجوع على المؤسسين بالتعويض بطلب يقدم لهيئة التحكيم المنصوص عليها بالقانون.$b$, E'\n', E'\r\n')),
    (58, 0, ARRAY['9e73f76113eac510b689794868352223']::text[], ARRAY['4f52f5a8aecca8131eecd870437719c9']::text[], '15efac5995d2f624c5dd7526eba46cd4', replace($b$على كل شركة طرحت أوراقا مالية لها في اكتتاب عام أن تقدم على مسئوليتها إلى الهيئة بيانا بالتعديلات التي تطرأ على نظامها الأساسي ونسب المساهمات في رأس مالها فور حدوثها وتقارير نصف سنوية عن نشاطها ونتائج أعمالها خلال الشهر التالي لانتهاء تلك المدة، على أن تتضمن هذه التقارير قائمتي المركز المالي ونتيجة النشاط مصدقا على ما ورد بهما من مراقب الحسابات، وذلك طبقا للنماذج المرافقة لهذه اللائحة.
ويتم إعداد التقارير عن نشاط شركات المساهمة والتوصية بالأسهم ونتائج أعمالها والقوائم المالية لها وفقا لمعايير المحاسبة المصرية ونماذج القوائم المالية الواردة بالملحق رقم (3).
كما يتم مراجعة حسابات الشركات المشار إليها وفقا لقواعد المراجعة الدولية.
وتسري هذه الأحكام على الشركات التي تباشر نشاطا أو أكثر من الأنشطة المبينة في المادة رقم (27) من القانون ولو لم تطرح أوراقا مالية لها في اكتتاب عام
*معدلة بقرار وزير الإقتصاد رقم 503 لسنة 1997$b$, E'\n', E'\r\n')),
    (59, 0, ARRAY['48e5e9aaf1836f28f03b7d2782713500']::text[], ARRAY['48589e41ff8ce5278b87b5d1f43debcc']::text[], 'f936e01636bef2968a25474336921a4f', replace($b$ملغاة
