    (61, 5, ARRAY['48e5e9aaf1836f28f03b7d2782713500']::text[], ARRAY['48589e41ff8ce5278b87b5d1f43debcc']::text[], 'f936e01636bef2968a25474336921a4f', replace($b$ملغاة
