    (62, 0, ARRAY['f6b948ff5c0bae1109c9ab07c582dd5f']::text[], ARRAY['be1a3f4cca2f71078719fe3f536aba3f']::text[], '75d114e75041a618fdb106769cb39d88', replace($b$ملغاة
*ألغيت بموجب قرار وزير الاستثمار رقم 12 لسنة 2007.$b$, E'\n', E'\r\n')),
    (63, 0, ARRAY['b387e6fc13ce89ebc1f2755a5dbd8633']::text[], ARRAY['ddb4068b95f8134988fdfef9992e7b30']::text[], '148ab70957cea80e5f801898c9fd55f6', replace($b$لا يجوز للشركة أو نظامها الأساسي وضع قيود على تداول أسهمها متى كانت من شركات الاكتتاب العام أو على الأسهم التي يتم قيدها ببورصات الأوراق المالية وذلك مع عدم الإخلال بالأوضاع المقررة عند تاريخ العمل بهذه اللائحة.$b$, E'\n', E'\r\n')),
    (64, 0, ARRAY['d03854b7f03c93acea75d74cb1f23f32']::text[], ARRAY['30215224d09aae1666db5a232203da0f']::text[], '6d09815d28a18bab574cf5d25e6e37d3', replace($b$إذا دخل في تكوين رأس مال شركة المساهمة وشركة التوصية بالأسهم عند التأسيس أو زيادة رأس المال أو الاندماج حصص عينية مادية أو معنوية وسواء كانت الحصة مقدمة من جميع المؤسسين والمكتتبين أو الشركاء أو بعضهم، وجب على المؤسسين أو على مجلس الإدارة أو الشريك أو الشركاء المديرين بحسب الأحوال طلب تقدير قيمة الحصة أو الحقوق المندمجة عن طريق اللجنة المختصة طبقا للقانون الواجب التطبيق.$b$, E'\n', E'\r\n')),
    (65, 0, ARRAY['ea153125831f8923c86ed1141fe2973f']::text[], ARRAY['7f4df081a1ce9c3e2c400d17a7aee2db']::text[], '43f35b26e89af9d022b4733607846f5d', replace($b$يشترط لإصدار أسهم مقابل الحصة العينية أو بمناسبة الاندماج أن تكون قيمتها مطابقة لقيمة الحصة أو الحقوق المندمجة كما حددتها لجنة التقييم المختصة.$b$, E'\n', E'\r\n')),
    (66, 0, ARRAY['70290c6b9930ad256786f6af4e2ac61b']::text[], ARRAY['d3814fa9ed86641f6fc9859b7ba13217']::text[], 'b08bff80d5befc8db1b04d847141472e', replace($b$تلتزم الجهة التي قدم إليها طلب التقدير بإخطار وكيل المؤسسين أو رئيس مجلس إدارة الشركة أو الشريك أو الشركاء المديرين بحسب الأحوال ومقدم الحصة العينية بقرار اللجنة المشكلة للتقييم خلال خمسة عشر يوما من تاريخ صدوره، وذلك بموجب خطاب بالبريد الموصى عليه بعلم الوصول.
ولكل ذي شأن التظلم من هذا التقدير خلال ثلاثين يوما من تاريخ الإخطار أمام لجنة التظلمات المنصوص عليها بالباب الخامس من القانون، وإلا كان التقدير نهائيا تلتزم به الجمعية التأسيسية أو الجمعية العامة حسب الأحوال، وذلك دون إخلال بحق مقدم الحصة العينية في الانسحاب أو أداء الفرق نقدا.
وعلى أصحاب الشأن سداد مبلغ تقدره الهيئة، على ذمة أتعاب لجنة التظلمات.$b$, E'\n', E'\r\n')),
    (67, 0, ARRAY['93e2460c5eff1dd3e4e13eedd5d7621e']::text[], ARRAY['929f3791b4a7c06aa3f7706f9d2cf6d5']::text[], 'ef70d75276e7833a4405e6d95eb59f51', replace($b$يسري في شأن التظلم الأحكام المتعلقة بالإجراءات التي تتبع أمام لجنة التظلمات.
وللجنة دعوة أصحاب الشأن لحضور جلساتها وسماع ما ترى سماعه من إيضاحات أو تطلب ما تراه من مستندات وبيانات.$b$, E'\n', E'\r\n')),
    (68, 0, ARRAY['1671cfba821969b6cfec72d949f7a6cb']::text[], ARRAY['a6fb9060985e3366de21e1f4de94a513']::text[], 'afd10c4efbffd391aa6db1f435cde722', replace($b$لا يجوز إصدار أسهم مقابل حصة عينية أو مقابل الحقوق المندمجة إلا بعد فوات ميعاد التظلم أو البت فيه.$b$, E'\n', E'\r\n')),
    (69, 0, ARRAY['a56d51622560414b67d2cfcbcac55f21']::text[], ARRAY['8e1b2fa1c620f4eac0881540e6fcc850']::text[], 'f260582069786c32938242bdb6f168f4', replace($b$وعلى مكاتب السجل التجاري موافاة الهيئة بأية بيانات يتم قيدها لديها عن الشركات المساهمة أو شركات التوصية بالأسهم خلال أسبوعين من تاريخ القيد.$b$, E'\n', E'\r\n')),
    (70, 0, ARRAY['ad373128641601c39187339550b09854']::text[], ARRAY['17c15bd00168e62f7840693174a2b8df']::text[], '89bb1f6c71463d27be0fd369bcb1d0b1', replace($b$يجوز لحملة السندات وصكوك التمويل والاوراق المالية الاخرى ذات الاصدار الواحد تكوين جماعة تهدف الى حماية المصالح المشتركة لاعضائها ومتابعة الاصدار حتى انتهائه.
ويجب ان تتضمن نشرة الاكتتاب او مذكرة المعلومات ، بحسب الاحوال ، نصا يفيد تحديد رغبة المكتتبين فى السندات وصكوك التمويل والاوراق المالية الاخرى فى الاشتراك فى عضوية جماعة حملة السندات من عدمه ، على ان يرفق بسند الاكتتاب اقرار من المكتتبين بالرغبة فى عضوية جماعة حملة السندات من عدمه.
وفى حالة اصدار سندات او صكوك التمويل او اوراق مالية اخرى على دفعات فى اطار برنامج اجمالى للاصدار ، يكون لحملة كل دفعة من السندات او صكوك التمويل او الاوراق المالية الاخرى الاشتراك فى الجماعة والمشاركة فى كافة اعمالها او قراراتها بنسبة ما يملكونه من سندات او صكوك تمويل او اوراق مالية اخرى الى اجمالى رصيد السندات او الصكوك او الاوراق المالية الاخرى القائم فى تاريخ الاشتراك فى الجماعة.
وتبين نشرة الاكتتاب او مذكرة المعلومات ، بحسب الاحوال ، كيفية تكوين فى هذه الحالة وطريقة اشتراك حملة كل دفعة فى الجماعة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (71, 0, ARRAY['e981757f39c6967b2d6df0e01517aeed']::text[], ARRAY['ee947d117985ef6013c4914739d3889c']::text[], 'f8a20b284d222452a2f9bc8c4be01af1', replace($b$يكون لجماعة حملة السندات وصكوك التمويل والاوراق المالية الاخرى ممثل قانونى من بين اعضائها، يتم اختياره فى اجتماع للجماعة بقرار من أغلبية حملة السندات او صكوك التمويل او الاوراق المالية الاخرى الحاضرة فى الاجتماع، ويتم اخطار الهيئة والجهات المرتبطة بالاصدار باسم ممثل الجماعة فور اختياره، ويتم الاخطار وفقا لوسائل النشر المحددة بالضوابط الصادرة من مجلس إدارة الهيئة.
وتحدد الجماعة فترة تمثيله لها ، ومن ينوب عنه عند غيابه ، والمكافأة المالية التى ترى الجماعة تقريرها له ، فاذا لم يتم اختياره خلال ثلاثة اشهر من تاريخ اول اجتماع دعى اليه لاختياره ، على الجهة المصدرة للسندات ابلاغ الهيئة بطلب تعيين ممثل للجماعة، وعلى رئيس الهيئة ان يصدر قرار بتعيين ممثل للجماعة خلال اشهر من تاريخ وصول الطلب للهيئة.
ويتم عزل الممثل القانونى للجماعة باغلبية حملة السندات او صكوك التمويل او الاوراق المالية الاخرى الحاضرة فى الاجتماع حال فقده احد الشروط المبينة فى هذه اللائحة او لغيرها من الاسباب، بناء على طلب من حملة (5%) من قيمة الاصدار او من الهيئة، ويجب ان يكون قرار العزل مسببا، مع اختيار ممثل قانونى آخر فى ذات الاجتماع بنفس الشروط والاجراءات الخاصة بالتعيين.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (72, 0, ARRAY['e6b427632d95ba9056df384626ce9599']::text[], ARRAY['09bf0340fdc372bbbb8249bc2e3d74ed']::text[], 'd208e3e20182baf650972a3444e1622d', replace($b$يجب ان يكون ممثل الجماعة او نائبه شخصا طبيعيا، سواء كان ذلك بصفته الشخصية او بصفته ممثلا عن شخص اعتبارى، ويجب الا يكون للممثل القانونى او نائبه علاقة مباشرة او غير مباشرة بالجهة مصدرة الاوراق المالية او الاطراف المرتبطة بعملية التوريق، او مصلحة تتعارض مع مصلحة حاملى تلك الاوراق، او ان يكون عضوا بمجلس ادارة او من الشركاء المديرين او من اعضاء مجلس المراقبة او من العاملين لدى شركة تملك أكثر من (10%) من رأس مال الجهة مصدرة الاوراق المالية او ضامنة لكل لو بعض ديون هذه الجهة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (73, 0, ARRAY['5b08f3252a2574d26a8912983dfe421a']::text[], ARRAY['a7f8f8cbb41dce9d5ccd4e676d85c201']::text[], 'c64917d45f4ebb244aa492d7a69edf78', replace($b$يجب على رئيس مجلس ادارة الجهة او العضو المنتدب للادارة والممثل القانونى للجماعة ان يخطر الهيئة بتشكيل الجماعة واسم ممثلها القانونى، خلال خمسة عشر يوما من تاريخ تشكيلها، وذلك وفقا لوسائل النشر المحددة بالضوابط الصادرة من مجلس ادارة الهيئة.
وعلى الممثل القانوني للجماعة أن يخطر كلا من الهيئة، ورئيس مجلس إدارة الشركة أو العضو المنتدب للإدارة بصورة موقعة منه من القرارات التي تصدرها الجماعة خلال خمسة عشر يوما من تاريخ صدورها.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (74, 0, ARRAY['d95515523cb3c9d370a007e057b6ffa8']::text[], ARRAY['b996c42c3ee0f665f9b03a24c47defb3']::text[], 'df5fbb2ce30f3f91f97d1e74fcc3382b', replace($b$يتولى الممثل القانونى للجماعة مباشرة الاختصاصات الاتية:
( أ ) رئاسة اجتماعات الجماعة ، وفى حالة غيابه ومن ينوب عنه تختار الجماعة من يحل محله فى رئاسة الاجتماع. (ب ) القيام باعمال الادارة اللازمة لتسيير امور الجماعة وحماية مصالحها ، وذلك طبقا للنظام الذى تضعه له الجماعة.
( ج ) تمثيل الجماعة فى مواجهة الجهة المصدرة والغير وامام القضاء.
( د ) رفع الدعاوى التى توافق الجماعة على اقامتها باسمها ، وذلك بغرض المحافظة على المصالح المشتركة لاعضائها، وبصفة خاصة الدعاوى المتعلقة بإبطال القرارات والاعمال الضارة بالجماعة من الجهة المصدرة ان كان لذلك مقتضى.
( هـ ) الدعوة لعقد الجماعة فى الحالات التى تستدعى ذلك لحماية لمصالحهم ، ا وفى حالة اتخاذ قرار بالجهة المصدرة يضر بمصالح حملة السندات او صكوك التمويل ، او فى حالة حدوث حالة اخلال وعدم سداد مستحقات حملة السندات او صكوك التمويل او الاوراق المالية الاخرى فى مواعيدها.
( و ) اى اختصاصات اخرى منصوص عليها فى نشرة الاكتتاب او مذكرة المعلومات ، بما لا يتعارض مع مصلحة الجماعة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (75, 0, ARRAY['7bdbad9aa065b9dde5717dfcac59321f']::text[], ARRAY['6ed3df7c370555f6032d2519e65a1d9f']::text[], '296979b7960e472211cc1638d70209f7', replace($b$يجب على الجهة المصدرة اخطار ممثل الجماعة بموعد جلسات الجمعية العامة او الجهة المختصة بذلك فى غير الشركات بحسب الاحوال، وموافاته بجميع الاوراق المرفقة بالاخطار على الوجه الذى يتم به اخطار المساهمين. ويكون الممثل القانونى للجماعة حق حضور اجتماعات الجمعية العامة للجهة المصدرة او الجهة المختصة بذلك فى غير الشركات بحسب الاحوال، وابداء ملاحظاته دون ان يكون له صوت معدود فى المداولات، ويكون له عرض قرارات وتوصيات الجماعة على مجلس ادارة الجهة المصدرة او الجمعية العامة للجهة المصدرة، ويجب إثبات محتواها فى محضر الجلسة.
ولا يجوز للممثل القانونى للجماعة التدخل فى ادارة الجهة المصدرة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (76, 0, ARRAY['3cab0d55b2aca0a2267f05ce04bc2274']::text[], ARRAY['dcc11a674feff8b49b008bb7694e0a24']::text[], '2890fd91e53601b845d12cca4ae2f42a', replace($b$تدعى للاجتماع، فى اى وقت، جماعة حملة السندات وصكوك التمويل والاوراق المالية الاخرى، وذلك فى الاحوال الاتية:
( أ ) اذا طلب الممثل القانونى للجماعة.
( ب ) اذا طلب مجلس ادارة الجهة المصدرة او الشريك او الشركاء المديرون بحسب الاحوال.
( ج) اذا طلب حملة مالا يقل عن (5%) من قيمة السندات وصكوك التمويل والاوراق المالية الاخرى بالجماعة بكتاب مسجل مصحوب بعلم الوصول من الجهة المصدرة او الممثل القانونى للجماعة . فاذا لم يتم الاجتماع خلال ثلاثين يوما جاز للطالبين او بعضهم ان يطلبوا من محكمة الامور المستعجلة الامر بتعيين ممثل مؤقت للجماعة يتولى الدعوة لعقد الاجتماع ورئاسته.
( د ) اذا طلبت الهيئة.
( هـ ) اذا طلب مصفى الجهة المصدرة خلال فترة التصفية.
( و ) فى اى حالة أخرى يتم النص عليها فى نشرة الاكتتاب او مذكرة المعلومات.
على ان يتضمن الطلب فى جميع الاحوال الموضوعات المطلوب عرضها على الجماعة.
كما تختص الجماعة بالنظر فى الموضوعات الآتية:
( أ ) التعديلات على بنود نشرة الاكتتاب او مذكرة المعلومات الخاصة بالسندات او الصكوك او الاوراق المالية الاخرى.
( ب ) تعديل العقود المرتبطة بعملية التوريق خلال عمر السندات وحالات انهاء تلك العقود.
(ج ) اجراء اى زيادة فى الاتعاب والعمولات والمصاريف التى يتم خصمها من محفظة الحقوق المالية المحالة خلال عمر سندات التوريق الصادرة فى مقابلها.
( د ) حدوث اى حالة من حالات الاخلال الواردة بنشرة الاكتتاب او مذكرة المعلومات او عدم سداد مستحقات حملة السندات او الاوراق المالية الاخرى فى تواريخ استحقاقها المحددة.
( هـ ) المسائل التى تطلب الهيئة عرضها على الجماعة.
( و ) موضوعات أخرى منصوص عليها بنشرة الاكتتاب او مذكرة المعلومات.
وتصدر قرارات الجماعة بالأغلبية الحاضرة، وذلك عدا القرارات المتعلقة بالبنود ارقام ( أ،د،هـ ) فتصدر بأغلبية ثلثى السندات او الصكوك الحاضرة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (77, 0, ARRAY['0a3c7df4e219fb62f51e26f4ef4657c9']::text[], ARRAY['ea33591215402f88ca4ce1258a19be8b']::text[], '6e7382b13e27588aaedb1b56ce9595ae', replace($b$يجب على كل من وجه الدعوة لاجتماع الجماعة ان يخطر الهيئة والجهة مصدرة الاوراق بالبيانات والاخطارات الموجهة للدعوة لعقد اجتماع للجماعة، وذلك فى ذات تاريخ الاخطار او الاعلان.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (78, 0, ARRAY['0374a8989ae7c3e498d9eea9f1b003a8']::text[], ARRAY['33dfc27afe79afcb1da503bc82667735']::text[], '890088f563e42b2bef2994542ae8a982', replace($b$يكون اجتماع الجماعة صحيحا بحضور الأغلبية الممثلة لقيمة السندات وصكوك التمويل والأوراق المالية الأخرى، فإذا لم يتوافر هذا النصاب في الاجتماع الأول كان الاجتماع الثاني صحيحا أيا كان عدد الحاضرين.$b$, E'\n', E'\r\n')),
    (79, 0, ARRAY['6de1164929672533aeecab7a160d61a1']::text[], ARRAY['6b8057d7b8518e67dccbaa1d8f07e91e']::text[], '686540e0adac43e6681c19774b4278d6', replace($b$تتضمن الدعوة الى اجتماع جماعة حملة السندات وصكوك التمويل و الاوراق المالية الاخرى البيانات المتطلبة لدعوة الجمعية العادية للشركة الواردة بحكم المادة ( 179 ) من اللائحة التنفيذية لقانون شركات المساهمة وشركات التوصية بالاسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد المشار اليه او الجهة المختصة بذلك فى غير الشركات بحسب الاحوال، على ان يضاف الى البيانات المبينة فى الدعوة للاجتماع بيان الاصدار او الاصدارات التى يدعى حملة اوراقها الى الاجتماع ، واسم وعنوان الشخص الذى يدعو الى الاجتماع وصفته، او قرار المحكمة بتعيين ممثل مؤقت للدعوة الى الاجتماع فى حالة وجوده.
وتتم الدعوة الى الاجتماع وفقا للطريقة المحددة بنشرة الاكتتاب او مذكرة المعلومات الخاصة بالاصدار، على ان يتم اخطار الهيئة مسبقا بها ونشرها وفقا للضوابط المحددة بالنشر الواردة بقرار مجلس ادارة الهيئة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (80, 0, ARRAY['d5bde9fb77dc0d89af5d76d60b857e5b']::text[], ARRAY['9840684e02288360e1494123a6758fcc']::text[], '32b209b37aec26f93bf34da97694e10c', replace($b$يحدد الشخص أو الجهة التي طلبت الدعوة إلى الاجتماع جدول الأعمال، ويجوز لحملة ما لا يقل عن 5% من القيمة الاسمية للسندات وصكوك التمويل والأوراق المالية الأخرى أن يطلبوا من الشخص أو الجهة التي لها حق الدعوة إدراج مسائل معينة في جدول الاجتماع لنظرها وإصدار قرارات في شأنها.
ولا يجوز مناقشة أو إصدار قرارات في شأن مسائل لم تدرج في جدول الاجتماع.$b$, E'\n', E'\r\n')),
    (81, 0, ARRAY['6c8f57383488d5515218bfeb49b8158c']::text[], ARRAY['e4fa231f1e808d4f97e8c359e7777baa']::text[], '4b07c1826f03a8cd0195406b26c85e44', replace($b$يكون من حق كل حامل سند او صك تمويل او ورقة مالية اخرى حضور اجتماعات جماعة حملة السندات وصكوك التمويل والاوراق المالية الاخرى سواء بنفسه او من ينيبه.
ويكون لحملة السندات وصكوك التمويل والاوراق المالية الاخرى التى تقرر استهلاكها دون ان يتم اداء قيمتها بالكامل ، سواء لافلاس الجهة المصدرة او لخلاف حول شروط رد قيمة السند او صك التمويل او أية ورقة مالية اخرى، الحق فى حضور الاجتماعات.
ولا يجوز ان يمثل حملة السندات او صكوك التمويل او الاوراق المالية الاخرى فى حضور اجتماعات الجماعة اعضاء مجلس ادارة الجهة مصدرة السندات او صكوك التمويل او الاوراق المالية الاخرى او اى شركة اخرى ضامنة لديونهم او اعضاء مجلس مراقبتها او مراقبى حساباتها او احد العاملين بها او اصول او فروع او ازواج الاشخاص المشار اليهم.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (82, 0, ARRAY['4173579c2a6bf51874fc457651331354']::text[], ARRAY['2a30e82c9420c19510eb31c24ed5a1cc']::text[], '2520e22ae1212bf1fd3cef87134dff54', replace($b$تجتمع جماعة حملة السندات وصكوك التمويل والاوراق المالية الاخرى فى مقر الجهة المصدرة او اى مكان آخر تحدده الجماعة للاجتماع فى المدينة التى بها مقر الجهة المصدرة، وتتحمل الجهة المصدرة نفقات الاجتماع والدعوة اليه وما يتقرر من مكافأة للممثل القانونى للجماعة، وذلك مالم تتضمن نشرة الاصدار تحديد اسلوب آخر لتحمل نفقات اجتماعات جماعة مالكى الصكوك ومكافآت ممثلها.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (83, 0, ARRAY['786e2e99ee57912e642b25be8ba449ea']::text[], ARRAY['df050c041a1099ec69348e32069839ea']::text[], 'cb4b444696c5a2867bb79b67d7fb9ba7', replace($b$مع مراعاة حكم الفقرة الثانية من هذه المادة ، يكون لجماعة حملة السندات وصكوك التمويل والاوراق المالية الاخرى ان تتخذ فى اجتماعاتها التى تتم طبقا لاحكام هذه اللائحة الاجراءات الاتية:
( أ ) اى اجراء يكون من شأنه حماية المصالح المشتركة لحملة السندات وصكوك التمويل والاوراق المالية الاخرى وتنفيذ الشروط التى تم على اساسها الاكتتاب.
(ب ) تقرير النفقات التى قد تترتب على اى من الاجراءات التى تتخذها.
( ج ) ابداء اى توصيات فى شأن من شئون الجهة المصدرة لتعرض على الجمعية العامة للمساهمين او مجلس ادارة الشركة المصدرة او الجهة المختصة بذلك فى غير الشركات بحسب الاحوال.
ولا يجوز لجماعة حملة السندات وصكوك التمويل والاوراق المالية الاخرى ان تتخذ اى اجراءات يترتب عليها زيادة اعباء اعضائها او عدم المساواة فى المعاملة بينهم.
*معدلة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (83, 1, ARRAY['c6e1b8ebab775bbe6db5d40772c81f4f']::text[], ARRAY['8e3ca835dcaa1c8ccb52339d52af52ae']::text[], '18a0d4e4a8194a2fc501ac20ddaa1a3a', replace($b$تشكيل جماعة مالكى الصكوك:
يجوز لمالكى الصكوك ذات الاصدار الواحد تكوين جماعة تهدف الى حماية مصالح مالكى الصكوك ومتابعة الاصدار حتى انتهائه.
ويجب ان تتضمن نشرة الاكتتاب او مذكرة المعلومات ، بحسب الاحوال ، نصا يفيد تحديد رغبة المكتتبين فى الصكوك فى الاشتراك فى عضوية جماعة مالكى الصكوك من عدمه ، على ان يرفق بسند الاكتتاب اقرار من المكتتبين بالرغبة فى عضوية جماعة مالكى الصكوك من عدمه.
على ان تظل تلك الجماعة قائمة منذ تاريخ تشكيلها ، وتنتهى بانتهاء اجل الصكوك ، او استهلاك قيمة الصكوك او اتفاق مالكى الصكوك على انهاء اعمالها.
وتخطر الهيئة بتشكيل الجماعة خلال خمسة عشر يوما من تاريخ تشكيلها ، على ان يتم اخطار الجهات المرتبطة بالصكوك المصدرة باسم ممثل الجماعة فور اختياره ، وعلى وجه الاخص الجهة المصدرة للصكوك ويتم الاخطار وفقا لوسائل النشر المحددة بالضوابط الصادرة من جلس ادارة الهيئة.
ويكون اختيار ممثل جماعة مالكى الصكوك او تعيينه او عزله وفقا لاحكام المادة (71) من هذه اللائحة ، ويراعى فى اختيار ممثل الجماعة ونائبه الا تكون لهما علاقة مباشرة او غير مباشرة بالجهة المصدرة او مصلحة تتعارض مع مصلحة جماعة مالكى الصكوك والا يكون قد حكم عليهما بأى عقوبة جناية او جنحة مخلة بالشرف او الامانة وان يكونا كاملا الاهلية ولم يحكم عليهما بالافلاس ما لم يرد اعتبارهما.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (83, 2, ARRAY['2c19f00982868e91716d3a7ba62ed94c']::text[], ARRAY['807e91138ee92a2a9ca26ea54b975532']::text[], '664ac8ba34a6094c309a566eb99a55f7', replace($b$يتولى الممثل القانونى لجماعة مالكى الصكوك دعوة الجماعة للانعقاد، وتجتمع الجماعة بمقر الجهة المصدرة للصكوك او بالمكان المحدد بنشرة الاكتتاب او مذكرة المعلومات.
ويسرى فى شأن اجراءات دعوة جماعة حملة الصكوك للانعقاد وكيفية الانعقاد والتصويت على قرارات الجماعة وعلاقة الجماعة بالجهة المصدرة للقواعد والاجراءات الواردة بهذا الفصل الخاصة بجماعة حملة السندات.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (83, 3, ARRAY['11048dc2359e706b0b71b5c1a48e4f43']::text[], ARRAY['7125a1bbe1d817a9c152632c29acd81f']::text[], '5180bc1bd4297429f5c9a48058ef9fd9', replace($b$مع عدم الاخلال باختصاصات جماعة حملة السندات الواردة بالمادة (83) من هذه اللائحة يكون لجماعة مالكى الصكوك متابعة لمصالحهم لدى الجهة المستفيدة وغيرها من الجهات ذات العلاقة بالاصدار ويكون لها اتخاذ اى اجراءات او تدابير لحماية حقوق الجماعة ، وعلى الاخص ما يلى:
1. متابعة استخدام حصيلة اصدار الصكوك فى الاغراض المحددة بنشرة الاكتتاب.
2. متابعة اى تصرفات يقوم بها المصدر او الجهة المستفيدة ولا يتفق مع نشرة الاكتتاب او مذكرة المعلومات وتؤثر سلبا على حقوق مالكى الصكوك ، واتخاذ اللازم بشأنه
3. متابعة توزيع الارباح او العوائد واتمام استرداد مالكى الصكوك لحقوقهم فى نهاية مدة الاصدار وفقا لنشرة الاكتتاب او مذكرة المعلومات للاصدار.
4. الموافقة على اى تعديلات تطرأ على نشرة الاكتتاب او مذكرة المعلومات او عقد الاصدار المبرم بين الجهة المصدرة والجهة المستفيدة وعوائده المتوقعة وطريقة توزيعها وفقا لطبيعة الصكوك المكتتب فيها وواجبات والتزامات الجهة المصدرة والجهة المستفيدة ومنظم الاصدار وآجال الصكوك وامكان تداولها او استردادها 5. القيام باى مهام او اختصاصات اخرى منصوص عليها فى نشرة الاكتتاب او مذكرة المعلومات ، بما لا يتعارض مع مصلحة الجماعة.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (83, 4, ARRAY['7615bbc9de46afcbb7c11fd75c6125dc']::text[], ARRAY['d289d5db2405c4fcd0fdd4171abbfb86']::text[], '2c7463372024e75c48747ed5957791c8', replace($b$مع مراعاة اختصاصات الممثل القانونى لجماعة حملة السندات الواردة بالمادة ( 74 ) من هذه اللائحة على الممثل القانونى لجماعة مالكى الصكوك القيام بما يلى:
1. الالتزام بما تضمنته نشرة الاكتتاب او مذكرة المعلومات من اختصاصات اخرى مرتبطة بالاصدار ، مع قيام الممثل القانونى للجماعة فى سبيل قيامه بمهامه بالتنسيق مع الجهات ذات العلاقة بالاصدار فى الاحوال التى تستوجب ذلك.
2. الدعوة لعقد جماعة مالكى الصكوك فورا لعرض اى بيانات او معلومات واردة من الجهة المستفيدة تؤثر تأثيرا جوهريا على الصكوك او على سير انجاز المشروع وكذا عرض الاجراءات التى اتخذتها الجهة المستفيدة لمواجهة ذلك.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (83, 5, ARRAY['d218147f057633e9ed4969ccb949abcc']::text[], ARRAY['13ef18994a6846a5e0900c84c2f8bfab']::text[], 'c07b7b45c6496315d128c7bfa0fc6dbf', replace($b$على الجهة المصدرة للصكوك اخطار ممثل جماعة مالكى الصكوك عن اى بيانات او معلومات تؤثر تأثيرا جوهريا على الصكوك او على سير انجاز المشروع وعن الاجراءات التى اتخذها لمواجهة ذلك على ان يتم الافصاح خلال ثلاثة ايام عمل من تاريخ توافر المعلومة.
وتتحمل الجهة المصدرة نفقات الاجتماع والدعوة اليه وما يتقرر من مكافأة للممثل القانونى، وذلك ما لم تتضمن نشرة الاصدار تحديد اسلوب آخر لتحمل نفقات اجتماعات جماعة مالكى الصكوك ومكافآت ممثلها .
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (83, 6, ARRAY['7f78b7a8182eb31565274915772702b0']::text[], ARRAY['e7926b06dfd4fc83467e377613533ff0']::text[], '7919ea62a4bf44fadf13584d6e3b2e81', replace($b$تسري الاحكام المنظمة لمالكى السندات وصكوك التمويل والاوراق المالية الاخرى الواردة بهذا الفصل فيما لم يرد بشانه نص خاص فى المواد المنظمة لجماعة مالكى الصكوك.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (84, 0, ARRAY['e8f7a408372e3e0b04c66a2f4d96fd33']::text[], ARRAY['1a09b8be8893039655f1e5747c20c6e3']::text[], '7c0e942ba70bfad73868cd5fac6354a1', replace($b$تسري الأحكام والأوضاع المقررة لدعوة الجمعية العامة العادية للشركة واجتماعاتها الواردة باللائحة التنفيذية للقانون رقم 159 لسنة 1981 على اجتماعات الجماعة وذلك ما لم يرد في شأنه نص خاص في هذا الفصل.$b$, E'\n', E'\r\n')),
    (85, 0, ARRAY['6c9b3fbbd3b946d837bac30e48228c66']::text[], ARRAY['09c7fe3c56df9d9ae7e887942bfedb07']::text[], '8d80386b5afd598acf33deb1416a7d3e', replace($b$يتم قيد وتداول الأوراق المالية ببورصات الأوراق المالية وفقا لأحكام القانون والأحكام الواردة بهذه اللائحة وغيرها من القرارات الصادرة تنفيذا له.$b$, E'\n', E'\r\n')),
    (85, 1, ARRAY['05f8d3418ec0ca127bcbc14c6fb67a0f']::text[], ARRAY['b73cfa3192fab8642391f8ee23599e5e']::text[], 'e1a0fd921e1bb34894d5014ea1749c5d', replace($b$يتعين على من يرغب فى قيد وطرح اوراق مالية بالبورصة المصرية ان يقوم باسيتفاء شروط ومتطلبات تسجيل الشركات والجهات الراغبة فى قيد وطرح اوراقها المالية بالبورصة المصرية وتقديم طلبه الى الهيئة وفقا للنماذج التى تعدها الهيئة لهذا الغرض.
ويجب ان تتضمن نشرات الطرح كافة البيانات المتعلقة بالطرح وعلى الاخص ما يلى:
البند الاول - موجز البيانات العامة عن الشركة مصدرة الاسهم محل الطرح:
1. تطور رأس المال المرخص به والمصدر والمدفوع.
2. هيكل مساهمى الشركة المالكين لنسبة (5%) فاكثر من رأسمال الشركة طبقا لبيان شركة الايداع والقيد المركزى.
3. بيان باعضاء مجلس ادارة الشركة ( تنفيذى - متفرغ - مستقل - ذوى الخبرة ).
4. المديرين التنفيذيين والعاملين.
5. عقود المعاوضة.
6. موقف ايداع اسهم الشركة بالايداع المركزى.
7. الموقف الضريبى للشركة ومدى وجود اعفاءات ضريبية.
8. موقف اهم القضايا المرفوعة من او ضد الشركة والشركات التابعة والمخصصات المالية المحددة للشركة محل الطرح.
9. بيان بالرهون والقروض الحالية والتسهيلات الائتمانية المرتبة على اصول الشركة والشركات التابعة
10. التامين على اصول الشركة.
11. بيان استثمارات (مساهمات) الشركة محل الطرح فى الشركات التابعة والشقيقة فى تاريخ تقديم نشرة الطرح.
12. نبذة مختصرة عن نشاط كل شركة من الشركات التابعة وتاريخ وتطور المساهمة فيها.
13. بيانات المساهمين الرئيسيين عارضى البيع فى عملية الطرح.
14. هيكل المساهمين الرئيسيين قبل الطرح وبعد الطرح المتوقع والبيع.
15. بيانات الاسهم المرهونة من رأس مال الشركة او المخطط رهنها او تجميدها.
16. الاسهم المتاحة للتداول (حرة التداول) فى تاريخ تقديم نشرة الطرح.
17. مراقبو حسابات الشركة والمستشارون القانونيون.
18. بيانات مسئولى الاتصال بالشركة.
البند الثانى - موجز ليند افصاحات هامة:
1. موجز افصاحات عن طبيعة اعمال الشركة.
2. موجز افصاحات تتعلق بعملية الطرح.
( اسباب الطرح - موقف المساهمين الرئيسيين وفقا لقواعد قيد وشطب الاوراق المالية - المساهمون المجمدة اسهمهم لمدد زمنية محددة وفقا لقرارات جمعية عامة غير عادية ).
3. افصاحات لاحقة لاجراءات ستقوم بها الشركة بعد تنفيذ الطرح.
البند الثالث : موجز تقرير المستشار المالى المستقل عن القيمة العادلة للسهم وتقرير مراقب الحسابات على التقرير ، واى اقرارات اخرى وعلى الاخص اقرار المستشار المالى المستقل واقرار من رئيس مجلس ادارة الشركة عن صحة وسلامة الافتراضات المقدمة للمستشار المالى المستقل لتحديد القيمة العادلة واقرار اعضاء مجلس الادارة الممثلين لاشخاص اعتبارية والممثلين لافراد ومجموعات مرتبطة حال وجود بيانات غير صحيحة او افتراضات مضللة
البند الرابع : موجز القوائم المالية التاريخية للشركة ( جداول مقارنة لثلاث سنوات ).
البند الخامس : احكم وشروط الطرح وفقا لكتاب مدير الطرح.
البند السادس : احكام وآلية استقرار سعر السهم عقب الطرح.
*مضافة بقرار رئيس مجلس الوزراء رقم 2479 لسنة 2018$b$, E'\n', E'\r\n')),
    (86, 0, ARRAY['bd1d873201fc4f2480b887b4e8ea8889']::text[], ARRAY['1b313c39ec26576b3cfd311c69d41aee']::text[], '5029f5d414b7d29b1e45bae7fcc1c782', replace($b$على البورصة إعداد وتجهيز الأدوات والوسائل الفنية اللازمة لقيد وتداول الأوراق المالية بها وممارسة أنشطتها الأخرى.
وعلى بورصتي القاهرة والإسكندرية إعداد وسائل الربط اللازمة لتنفيذ نظام تداول مشترك فيما بينهما.
ويتم تداول الأوراق المالية بالبورصة وفقا للنظام الذي تضعه إدارة البورصة وتعتمده الهيئة.$b$, E'\n', E'\r\n')),
    (87, 0, ARRAY['b45a37df4494c8f9509c9ef8efc5dea6']::text[], ARRAY['153b4640eec59278ce0904f16880525f']::text[], 'be9c4d9e0905b2d77a39663ccca963f6', replace($b$يجب على كل شركة أو جهة قيدت لها أوراق مالية بالبورصة أن توافي إدارة البورصة بما يأتي:
1. الوثائق الخاصة بالتعديلات التي أدخلت على نظامها وذلك خلال خمسة عشر يوما من تاريخ سريانها.
2. صورة من الميزانية والقوائم المالية، وأسماء مجلس الإدارة، والتقارير التي يعدها المجلس أو مراقب الحسابات وذلك خلال خمسة عشر يوما من تاريخ إقرارها.
3. بيان نصف سنوي يتضمن قيمة مساهمات أعضاء مجلس إدارة الشركة والعاملين لديها وأسماء المساهمين الذين يملكون 10% على الأقل من أسهمها.
4. أية وثائق أخرى تحددها الهيئة.
مع عدم الإخلال بحكم المادة (101) من هذه اللائحة لا يجوز لغير شركات السمسرة الحصول على أي من المستندات المبينه بهذه المادة أو أية بيانات منها.$b$, E'\n', E'\r\n')),
    (88, 0, ARRAY['cd685064c1db9b22ddbdd0a3460a56b2']::text[], ARRAY['fe37d1818af37500e3ae2b600c3230eb']::text[], '33388526556ee327f7ca5e196b27be8f', replace($b$ينشأ بكل بورصة سجل لقيد الأشخاص الذين يمثلون شركات السمسرة في مباشرة عمليات التداول بالبورصة، ويتم القيد به بقرار من إدارة البورصة على أن تخطر الهيئة بأسماء من يتم قيدهم خلال أسبوع من تاريخ القيد.$b$, E'\n', E'\r\n')),
    (89, 0, ARRAY['8bf26f63d618ded2c34ee3c98293cdb3']::text[], ARRAY['943807c31df52bcd8f79ee0555372ea3']::text[], '3445fca1d7c0584d4fea2acdeb5986dc', replace($b$يشترط فيمن يباشر عمليات التداول بالبورصة ممثلا لشركة السمسرة ما يأتي:
1. أن يكون متمتعا بالأهلية القانونية.
2. أن يكون حسن السمعة.
3. ألا يكون قد سبق فصله تأديبيا من الخدمة أو منعه تأديبيا بصفة نهائية من مزاولة مهنة السمسرة أو أي مهنة حرة أو حكم عليه بعقوبة جناية أو جنحة في جريمة ماسة بالشرف أو الأمانة أو بعقوبة مقيدة للحرية في إحدى الجرائم المنصوص عليها في قوانين الشركات أو التجارة أو قانون سوق رأس المال أو حكم بشهر إفلاسه.
4. استيفاء الخبرة أو اجتياز الاختبارات أو الدراسات التي يصدر بشأنها أو بتنظيمها قرار من الهيئة.
5. أن يكون متفرغا ولا يعمل بأي وجه وبأية صفة في شركة سمسرة أخرى أو في الأعمال التجارية.
6. أن يكون حاصلا على مؤهل عال.
يستثنى من الشرطين الواردين في البندين 4، 6 السماسرة والوسطاء والمندوبين الرئيسيين المقيدين في تاريخ العمل بالقانون ببورصتي القاهرة والإسكندرية.
ولصاحب الشأن التظلم أمام لجنة التظلمات المنصوص عليها في القانون من قرار الهيئة بالامتناع عن القيد أو برفضه أو بشطب القيد أو بوقفه.$b$, E'\n', E'\r\n')),
    (89, 1, ARRAY['9884134facb6c2f97eed0c631da6bfe8']::text[], ARRAY['b293dc89236366a2ef3cb4d184c1060e']::text[], '5df298791336c224bd87352d778d1de6', replace($b$تمسك كل من البورصة سجلا تقيد به الشركات المرخص لها من الهيئة بالعمل فى مجال الاوراق المالية التى تباشر نشاطها بها ويتم القيد مقابل الرسم والاشتراك المقررين بالمادة (19) من قانون سوق رأس المال. ويصدر بالأحكام والشروط المنظمة لقيد تلك الشركات بالبورصة قرار من مجلس ادارتها ولايكون هذا القرار نافذا الا بعد اعتماده من الهيئة.
*معدلة بقرار وزير الصناعة والتجارة رقم 383 لسنة 2004$b$, E'\n', E'\r\n')),
    (89, 2, ARRAY['42ee61247a4684b1e6155ac05a5a14de']::text[], ARRAY['51072da31a9ab46c3a7ca449e295d4c4']::text[], '7c3678ca87deb3c39f96b96b517ea0d6', replace($b$تكون الشركات المقيدة بالبورصة وفقا للمادة السابقة اعضاء بها ويصدر بقواعد العضوية بالبورصة قرار من مجلس ادارة البورصة يعمل به بعد اعتماده من الهيئة.
*معدلة بقرار وزير الصناعة والتجارة رقم 383 لسنة 2004$b$, E'\n', E'\r\n')),
    (89, 3, ARRAY['45dbe4c34d6d6faea1ee8eb35132eac1']::text[], ARRAY['a3c06139fb349b76c46b17b7d4884159']::text[], '9a134162bac213cf9686a9963dcf0019', replace($b$تكون العضوية على النحو المبين فيما يلى:
1. عضو منفذ يقوم بالتسوية وتنفيذ عمليات الشراء بالهامش.
2. عضو منفذ يقوم بالتسوية.
3. عضو منفذ يقوم بالتسوية من خلال احد امناء الحفظ.
4. المتعاملون الرئيسيون ويقومون بمزاولة نشاط التعامل فى السندات الحكومية.
5. أمناء الحفظ.
*معدلة بقرار وزير الصناعة والتجارة رقم 383 لسنة 2004$b$, E'\n', E'\r\n')),
    (89, 4, ARRAY['ea0460ee02fea6d7a9ea9e20f6a2de1d']::text[], ARRAY['5e8c6cd9a17f03e0f933887ae6dd710b']::text[], '8b74b934f56f0d4aea0f96d2f8f2999e', replace($b$تختص البورصة بالتحقيق من استمرار توافر المعايير والاشتراطات الفنية والمالية لكل عضو بها. وعلى البورصة اخطار الهيئة بما يصدر عن الاعضاء او المديرين لديهم او ممثليهم او المندوبين عنهم اثناء مزاولة العمل داخل البورصة من مخالفات لأحكام قانون سوق رأس المال وقانون الابداع والقيد المركزى الأوراق المالية المشار اليهما ولائحتهما التنفيذية والقرارات الصادرة تنفيذا لها.
*معدلة بقرار وزير الصناعة والتجارة رقم 383 لسنة 2004$b$, E'\n', E'\r\n')),
    (89, 5, ARRAY['5008fdf77eb8e780dbe586ab51fd4ceb']::text[], ARRAY['56dc6cc65cd9dd6655009327e15ca1b2']::text[], 'be3c0186b634c47308d651cddcff538d', replace($b$وفى جميع الاحوال التى تتطلب اجراء تفتيش على اعمال العضو لسبب يتعلق بأوضاعه او بمزاولة نشاطه فى البورصة يتعين على البورصة ابلاغ الهيئة فورا لأجراء التفتيش اللازم وللهيئة فى سبيل ذلك الاستعانة بالعاملين بالبورصة الذين يرشحهم رئيسها للجنة العضوية بالبورصة فى حالة مخالفة العضو او اى من مديريه او مندوبه او ممثليه لدى البورصة لأحكام قانون سوق رأس المال وقانون الايداع والقيد المركزى او لائحتهما التنفيذية او القرارات الصادرة تنفيذا لها اتخاذا بحد التدابير الاتية:
1. التنبية الى المخالفة وعدم تكرارها.
2. الانذار باتخاذ التدابير المنصوص عليها فى البند (3) التالى.
3. حظر استفادة العضو من نظم التداول المعمول بها فى البورصة والخدمات والتسهيلات التى تتيحها البورصة للعمل بها وكذلك حظر تواجد اى من العاملين لدى العضو فى قاعة التداول وذلك للمدة التى تحددها لجنة العضوية.
وفى جميع الاحوال يجوز لصاحب الشأن التظلم من قرار لجنة العضوية فى هذا الشأن امام الهيئة خلال خمسة عشر يوما من تاريخ ابلاغه بالقرار.
