    (93, 0, ARRAY['b47253cdb90bba92cced47dd87563b59']::text[], ARRAY['92cb67960822ea82fdf60e207618cb77']::text[], '476962c789030f759c32c8c878aeec3c', replace($b$تقوم الهيئة بمراقبة سوق التداول والتأكد من أن التعامل يتم على أوراق مالية سليمة، وأن عقد العمليات بالبورصة غير مشوب بالغش أو النصب أو الاحتيال أو الاستغلال أو المضاربات الوهمية.$b$, E'\n', E'\r\n')),
    (94, 0, ARRAY['13729f3dd1a04f0f143572c48fc38fee']::text[], ARRAY['a485f64af26ad375fc23ac2c40528b97']::text[], '585223dfb16cccf7839da214f6cc0a6c', replace($b$تضع البورصة نظم العمل والقواعد التي من شأنها ضمان سلامة عمليات التداول وحسن أداء البورصة لوظائفها. تشكل إدارة البورصة لجنة لمراقبة عمليات التداول اليومي والتحقق من تطبيق القوانين والقرارات وحل الخلافات التي قد تنشأ عن هذه العمليات.$b$, E'\n', E'\r\n')),
    (95, 0, ARRAY['0e6a938afd4d6564b7804563269eabe7']::text[], ARRAY['f4de7222ccea1d904be0a7e9646c2288']::text[], 'c245b0359ba290dd3e7b09d6cd4f2ad2', replace($b$يجب على شركة السمسرة عرض أوامر العملاء خلال المدة وبالشروط المحددة بأوامرهم، وإذا لم يحدد العميل أجلا لتنفيذ الأمر وجب على الشركة عرضه في أول جلسة تالية لوروده.
يتم تنفيذ الأوامر بحسب تاريخ وساعة ورودها لشركة السمسرة كما يكون تنفيذ الأوامر التي تعطى لممثل الشركة أثناء التداول وفقا لأولوية ورود تلك الأوامر.
كما يجب على الشركة استكمال إجراءات عقد العملية وإخطار البورصة والعميل بتنفيذها خلال يوم العمل التالي من عقد العملية.$b$, E'\n', E'\r\n')),
    (96, 0, ARRAY['1bbe3fbd3069097b2657ef902569b361']::text[], ARRAY['89d9f4b35d9e66b666b8304fb19b175c']::text[], '8707511bbdf1d629b9f88415b5e02a56', replace($b$تلتزم شركة السمسرة التي نفذت عملية على خلاف أوامر العميل أو على ورقة مالية غير جائز تداولها قانونا أو محجوز عليها بتسليم ورقة غيرها خلال أسبوع من تاريخ المطالبة، وإلا وجب عليها تعويض العميل، وذلك دون إخلال بحقها في الرجوع على المتسبب بالتعويض.$b$, E'\n', E'\r\n')),
    (97, 0, ARRAY['c585046206582c68bcfecb9f3723e60d']::text[], ARRAY['81184fb07d440d63afccb779778c83a8']::text[], '9f7f6b193956a98e3ea9927f282262c1', replace($b$يجوز التعامل على اى عدد من الاوراق المالية.
