    (104, 0, ARRAY['0df939e218178a47c846e925a73b75e6']::text[], ARRAY['38647965d548cc8368590cab6cac9e7e']::text[], '70f44a28f2d15f460d6cd5c350423249', replace($b$يجوز بموافقة مجلس ادارة الهيئة انشاء بورصات خاصة، تكون لها الشخصية المعنوية الخاصة، وتتخذ شكل شركة مساهمة ويقتصر التداول فيها على نوع او اكثر من الاوراق المالية.
