    (109, 0, ARRAY['623f4c11c6725d87965c693caebfa1f8']::text[], ARRAY['f39f183133c0d4d0bd97dc515607deda']::text[], '493b7f2216f1591707a237d93744c7d4', replace($b$تنشأ بورصة للعقود الآجلة، يتم تداول فيها على العقود التى تشتق قيمتها من قيمة اصول مالية او عينية او مؤشرات الاسعار او اوراق مالية او ادوات مالية او غيرها من المؤشرات التى تحددها الهيئة، سواء كانت فى شكل عقود مستقبلية او عقود خيارات او عقود المبادلة وغيرها من العقود النمطية.
