    (188, 0, ARRAY['fe0678e6e14d56c74a2aab507c4915e8']::text[], ARRAY['3704d72a94459aa779551ed760db99dc']::text[], '2942f114d2d8b941e009dfebf688c2c5', replace($b$تقوم الهيئة بفحص طلبات التأسيس والبت فيها خلال ثلاثين يوما من تاريخ تقديم الأوراق إليها مستوفاة، وفي حالة الموافقة تؤشر الهيئة على نسختين من نظام الاتحاد بما يفيد تسجيله ورقمه وتاريخه، وترسل نسخة منها إلى الاتحاد مرفقا بها شهادة التسجيل وتحتفظ بالنسخة الثانية.$b$, E'\n', E'\r\n')),
    (189, 0, ARRAY['85cc80148cb59800bba2c1c8746c5f1c']::text[], ARRAY['c86624c5e5555534401348c4e566aab8']::text[], '1a00a9840cafefc5a1924f862a54069c', replace($b$على الهيئة إذا رفضت طلب تأسيس الاتحاد أن تخطر المؤسسين بذلك مع بيان أسباب الرفض بكتاب موصى عليه مرفقا به الأوراق السابق تقديمها بعد الاحتفاظ بنسخة من كل منها، ولذوي الشأن التظلم أمام لجنة التظلمات المنصوص عليها في المادة (50) من القانون من القرار الصادر برفض تسجيل الاتحاد وذلك خلال ثلاثين يوما من تاريخ إبلاغهم قرار الرفض.$b$, E'\n', E'\r\n')),
    (190, 0, ARRAY['8657103bddc17b16de5a39279b65adea']::text[], ARRAY['562475375360c6afd17c197d6f170e07']::text[], '0778c90948291f9724169d68531efa23', replace($b$يتم إنشاء الاتحاد بقرار من الهيئة.
وتتولى الهيئة تسجيل نظامه في السجل المعد لذلك.
وتثبت الشخصية المعنوية له من اليوم التالي لصدور قرار إنشائه.$b$, E'\n', E'\r\n')),
    (191, 0, ARRAY['27cd949f15e2500d18db86fcaa8ed8df']::text[], ARRAY['72d17db485b0d46034bb7a33a6423499']::text[], 'a72f7f949871ebda30f55f5017018ada', replace($b$يكون للاتحاد تملك بعض أسهم الشركة الاسمية لصالح أعضائه، وذلك بالوسائل الآتية:
1. بموافقة جماعة المؤسسين للشركة بالقيمة والشروط التي يتم الاتفاق عليها.
2. بموافقة الجمعية العامة غير العادية للشركة عن طريق زيادة رأس مالها وتخصيص الزيادة كلها أو بعضها للاتحاد بالقيمة والشروط التي يتم الاتفاق عليها.
