    (271, 0, ARRAY['fdc26d9a84ae175fa6279a10f10d9a8f']::text[], ARRAY['649d27d6306d6c79588508810fbe8ebb']::text[], 'c1b5d731e006fec4643dfaf364003b76', replace($b$يجب أن تتوافر لدى الشركة الشروط والمواصفات التي يصدر بها قرار من مجلس إدارة الهيئة على أن تتضمن شروط تجهيز المقر، والتقارير الداخلية الواجب إصدارها، والقواعد الداخلية للرقابة والمراجعة المالية وشروط الكفاءة اللازمة في القائمين على إدارة الشركة، كما تلتزم الشركة بأن تفصل حسابات نشاط التعامل والوساطة والسمسرة في السندات عن حسابات أي نشاط آخر يرخص لها بمزاولته.
