    (272, 0, ARRAY['fac39669189be459a5b0d9b807ac1f88']::text[], ARRAY['f12b154381363bf0c3ef314f483dc117']::text[], 'c06f600ca19d0e8089946a62ee7102fc', replace($b$يجوز للشركة أن تبرم اتفاقات تتضمن الأحكام المنظمة لعمليات إعادة شراء السندات بعد بيعها وحقوق والتزامات أطراف الاتفاق ، ويتم تنفيذ هذه الاتفاقات بموجب تبادل وثائق يبيع بموجبها أحد أطراف الاتفاق سندات إلى الطرف الآخر مع التزامهما بإعادة بيعها للطرف الأول في تاريخ لاحق.
وتعد الهيئة نماذج للاتفاقات والوثائق المشار إليها على أن يتضمن نموذج الاتفاق أسلوب تسوية أو حسم المنازعات التي تنشأ بين أطرافه ، وأن يكون من بين عناصر نموذج الوثيقة نوع السندات محل التعامل وتاريخ استحقاقها والأسعار المتفق عليها بالنسبة للبيع وإعادة الشراء.$b$, E'\n', E'\r\n')),
    (273, 0, ARRAY['b384f1898d5f5c623872f63a2f439eda']::text[], ARRAY['6cef0832400cf35e363e2d5c8ccb72ae']::text[], '21b4e06b389699f0365ddf0667a3f28d', replace($b$على الشركة أن تفصح لعملائها كتابة وقبل تنفيذ أية عملية، عما إذا كان تعاملها معهم على سندات لحسابها الخاص أم لحساب عملائها وعن تعليمات التسوية والمقاصة بالإضافة إلى العمولة التي تتقاضاها الشركة إذا كان التعامل لحساب أحد عملائها.
* مضافة بقرار وزير الاقتصاد رقم 44 لسنة 2000.$b$, E'\n', E'\r\n')),
    (274, 0, ARRAY['974eb6458f9833f387041d1b8174dea6']::text[], ARRAY['2bbab4c97a47750af3f5584432b17624']::text[], 'cf9aabb5a89b28ee3aa86a4900a18c35', replace($b$إذا كان للسند محل التعامل أو للجهة التي أصدرته أو الضامنة لإصداره تصنيف إئتماني، تعين على الشركة أن تفصح لعملائها عن أخر تصنيف للسند قبل إتمام التعامل عليه، على أن تبين لهم أن التصنيف لا يعني التوصية بالبيع أو الشراء أو الاحتفاظ بالسند، وأنه قابل للتعديل.
وفي حالة عدم وجود مثل هذا التصنيف ، أو إذا كان قد تم تعديله خلال الشهر السابق على التعامل على السند، تعين على الشركة أن تفصح لعملائها عن ذلك وعن طبيعة التعديل.
* مضافة بقرار وزير الاقتصاد رقم 44 لسنة 2000.$b$, E'\n', E'\r\n')),
    (275, 0, ARRAY['12f51cad45a30ac4aa9d8f3df0e3b552']::text[], ARRAY['9ecc72ab7242cc68b98c8c70ec6f7052']::text[], 'd24794200dc58deec7dde8c11b804ed4', replace($b$على الشركة أن تخطر الهيئة يومياً بإجمالي القيمة السوقية لما تحتفظ به من سندات، وذلك في الوقت وعلى النحو الذي تحدده الهيئة ووفقاً للنموذج الذي تعده لهذا الغرض.
ويتم تحديد القيمة السوقية للسندات وفقاً لسعر تداولها في اليوم السابق، وفي حالة عدم التداول يتحدد سعرها قياساً على أسعار تداول السندات المشابهة من حيث الشروط والتصنيف الائتماني . فإذا لم تتوافر أسعار تداول سندات مشابهة، تعين على الشركة تحديد السعر وفقاً لما تبديه شركتان أخرتان على الأقل عن الثمن الذي تقبلان التعامل به على السند.
وللهيئة أن تطلب من الشركة أن تقدم لها ما تراه ضرورياً من التقارير الإضافية.
