    (280, 0, ARRAY['7e50f24e44c4805f047f98448883d007']::text[], ARRAY['f362cd47b41d6b742589b840f13891eb']::text[], '421f0b103f6e97ff9a203ceb59dd0419', replace($b$تسري على الشركة الأحكام الواردة في هذه اللائحة بشأن شركات السمسرة في الأوراق المالية ، كما يسري على ما تقوم به من تغطية للاكتتاب في السندات الأحكام الواردة في هذه اللائحة بشأن شركات ترويج وتغطية الاكتتاب في الأوراق المالية، وذلك كله فيما لم يرد بشأنه نص خاص في هذا الباب.
