    (281, 0, ARRAY['a2400f7ef935754da78db9863a6af05a']::text[], ARRAY['977f7e8615488a3d233263409dff1765']::text[], 'c85e29b0e6079329bcca0e695a92c862', replace($b$يقصد بلفظ (الشركة) في تطبيق أحكام هذا الباب شركات تقييم وتصنيف وترتيب الأوراق المالية وشركات تقييم وتصنيف وترتيب الأوراق المالية للشركات المتوسطة والصغيرة المرخص لها بمزاولة هذا النشاط وفقا لأحكام قانون سوق رأس المال المشار اليه والقرارات الصادرة تنفيذا له.
